      };
      [3] = {
      ["NAME"] = "Mina del Abismo de Plata"; 
      ["LORE"] = "El Abismo de Plata es una mansión abandonada hace mucho tiempo, antes de su finalización. El hallazgo de antiguas ruinas élficas y de un troll llevó a Thorin y a Gandalf el Gris a sellarla."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "14.38S"; 
