      [2] = {
      ["NAME"] = "Paso Este de Nan Wathren"; 
      ["LORE"] = "El paso oriental fue antaño la poterna de la fortaleza de Nan Wathren. Hoy se ha convertido en una vía de suministro para los trasgos que ahora habitan las ruinas de esta otrora orgullosa ciudadela."; 
      ["POINTS"] = {
