  -- Comarca / Los lugares de interés de la Comarca
  [1879071669] = {
      [1] = {
      ["NAME"] = "El Árbol de la Fiesta"; 
      ["LORE"] = "Este enorme árbol ha sido desde hace mucho tiempo un lugar donde los hobbits de la Comarca celebran ocasiones festivas. Situado en las afueras de la propia Hobbiton, puede verse desde bastante lejos, y durante las festividades a menudo se cuelgan decenas de serpentinas y faroles brillantes que proporcionan un ambiente alegre para casi cualquier evento."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "29.81S"; 
          ["LONG"] = "71.48W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Escenario de Methel"; 
      ["LORE"] = "Se dice que cuando el viejo Bilbo Bolsón regresó de sus andanzas, volvió con mucha más riqueza de la que tenía antes de marcharse.\n\nAunque abundan los rumores sobre el origen y la naturaleza dudosa de sus riquezas, entre las obras que financió en la Comarca estuvo el escenario Methel, sobre el cual los hobbits con inclinaciones artísticas son invitados a actuar y entretener a sus congéneres durante las festividades.\n\nPor supuesto, Bilbo ha vuelto a desaparecer recientemente — avivando las viejas habladurías sobre sus aventuras impropias — pero muchos de los habitantes de la Comarca siguen apreciando las causas en las que invirtió su dinero."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "32.60S"; 
          ["LONG"] = "69.92W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Torre de Stock"; 
      ["LORE"] = "La Stocktower es una curiosa vieja ruina arnoriana que vigila cerca del Puente del Brandivino.\n\nQuedan pocas ruinas de ese tipo en la Comarca, pues hace mucho tiempo los hobbits industriosos las desmontaron para construir residencias más modernas; sin embargo, la Stocktower se ha convertido en una especie de ícono y se sabe que niños hobbits traviesos frecuentan la ruina a pesar de las reprimendas de sus padres."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "33.02S"; 
          ["LONG"] = "63.57W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "La Cantera"; 
      ["LORE"] = "Durante mucho tiempo, los enanos no se veían con mucha frecuencia en la Comarca y traer piedra desde tierras lejanas era caro, por lo que los hobbits construyeron su propia cantera para suplir las necesidades de constructores y canteros.\n\nRecientemente, sin embargo, han estado disponibles piedras de mejor calidad desde el Oeste, por lo que la cantera ha caído en desuso y se ha llenado de alimañas peligrosas."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "27.67S"; 
          ["LONG"] = "65.59W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Muro de los Campos del Puente"; 
      ["LORE"] = "El Muro de Campos del Puente es uno de los pocos vestigios que quedan del antiguo Reino de Arnor dentro de los límites de la Comarca.\n\nEl granjero Barroso ha estado amenazando con derribarlo durante años para construir muros para sus propios campos, pero algunas de las familias hobbit más acomodadas de Cavada Grande se lo han impedido en los consejos de la Comarca, exigiendo que el muro se preserve por motivos históricos. Así que todavía sigue en pie."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "30.47S"; 
          ["LONG"] = "64.12W"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "El Gran Sauce"; 
      ["LORE"] = "Aunque no es tan conocido como el Árbol de la Fiesta, el Gran Sauce es considerado mucho más misterioso y romántico por los hobbits jóvenes de la Comarca.\n\nAbundan las leyendas sobre elfos que viajan hacia el Oeste y pasan sus veladas en misteriosas celebraciones bajo sus ramas, y los jóvenes hobbits a menudo acuden allí para declarar sus intenciones románticas, quizá esperando que un poco de magia les dé suerte y valor suficiente para pronunciar las palabras."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "33.61S"; 
          ["LONG"] = "70.41W"; 
        }; 
      }; 
      };
  };
