  -- Evendim / Tumbas de Evendim
  [1879089144] = {
      [1] = {
      ["NAME"] = "Haudh Eärendur"; 
      ["LORE"] = "La tumba de Eärendur, hijo de Elendur.\n\nEärendur fue el décimo y último rey de los reyes de Arnor. Tras su muerte, el reino de Arnor se dividió entre sus hijos en los reinos de Arthedain, Cardolan y Rhudaur. Fue durante este periodo en que la capital se movió a Fornost, y la vieja ciudad de Annúminas fue finalmente abandonada tras muchos años de declive."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "16.69S"; 
          ["LONG"] = "66.62W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Haudh Elendur"; 
      ["LORE"] = "La tumba de Elendir, hijo de Valandur. Como el noveno reino de Arnor, Elendur tuvo uno de los más largos reinados de todos, gobernando a la gente de Arnor durante ciento veinticinco años."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "16.30S"; 
          ["LONG"] = "66.02W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Haudh Valandur"; 
      ["LORE"] = "La tumba de Valandur, hijo de Tarondor. La historia no menciona mucho al octavo rey de Arnor, excepto por su muerte violenta en misteriosas circunstancias alrededor del quincuagésimo año de su reinado. Quizá una señal premonitoria del conflicto que iba a caer sobre los Reinos del Norte en los años venideros."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "16.94S"; 
          ["LONG"] = "66.63W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Haudh Elendil"; 
      ["LORE"] = "La tumba de Elendil, hijo de Amandil. Elendil fue el primer rey y fundador del reino de Arnor, adonde había huido cuando llegó a la Tierra Media escapando de la gran ruina de Númenor. Elendil luchó junto a Gil-galad como el líder de la Última Alianza y murió durante el Asedio de Barad-dûr, a manos de Sauron.\n\nTras su muerte, Elendil fue enterrado secretamente en Halifirien lejos hacia el sur, pero algunos de estandartes y efectos personales más importantes fueron colocados simbólicamente en la tumba de Annúminas en su lugar..."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "16.67S"; 
          ["LONG"] = "66.97W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Haudh Tarondor"; 
      ["LORE"] = "La tumba de Tarondor, hijo de Tarcil. El reinado del séptimo rey de Arnor fue marcado por una época de paz relativa, ya que la contienda que consumiría y con el tiempo destruiría los Reinos del Norte todavía no había comenzado."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "16.87S"; 
          ["LONG"] = "66.14W"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "Haudh Eldacar"; 
      ["LORE"] = "La tumba de Eldacar, hijo de Valandil. Eldacar gobernó como cuarto rey de Arnor, y fue el nieto de Isildur. Se cree que Eldacar reinó durante una época de paz que se extendía desde la derrota de Sauron en la guerra de la Última Alianza a manos de su abuelo, pero la mayoría de los registros de esta época en Arnor han sido destruidos."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "17.30S"; 
          ["LONG"] = "67.19W"; 
        }; 
      }; 
      };
      [7] = {
      ["NAME"] = "Haudh Tarcil"; 
      ["LORE"] = "La tumba de Tarcil, hijo de Arantar. Tarcil fue el sexto rey de Arnor y su reinado duró aproximadamente ochenta años antes de que la corona pasara a su hijo, Tarondor."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "17.13S"; 
          ["LONG"] = "66.02W"; 
        }; 
      }; 
      };
      [8] = {
      ["NAME"] = "Haudh Arantar"; 
      ["LORE"] = "La tumba de Arantar, hijo de Eldacar. Aunque se dice que el reinado del quinto rey de Arnor duró casi un siglo, la mayoría de los registros de esta época se perdieron en la caída de los Reinos del Norte, y poco se sabe de su mandato."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "18.02S"; 
          ["LONG"] = "66.54W"; 
        }; 
      }; 
      };
  };
  -- Evendim / Ruinas de Evendim
  [1879089145] = {
      [1] = {
      ["NAME"] = "Tham Nambarth"; 
      ["LORE"] = "Varias de las grandes familias de Annúminas construyeron mansiones palaciegas en las colinas de los Campos de Evendim, mostrando su riqueza y prosperidad a lo largo y ancho de la región, ofreciéndoles residencias veraniegas desde la que podían supervisar sus extensos dominios de ricas tierras de cultivo.\n\nAunque no tan extravagantes como algunos de los palacios construidos más tardes, Tham Nambarth era el más antiguo y más cercano a la ciudad y por ello considerado el más prestigioso de todos tras el de la familia real en Tinnudir."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "12.05S"; 
          ["LONG"] = "65.56W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Tham Varan"; 
      ["LORE"] = "El dominio de Tham Varan perteneció una vez a una de las más antiguas y prestigiosas familias de Annúminas. Eran conocidos por largas y a veces extrañas contiendas por conseguir influencia en las cortes reales de Arnor contra sus archirivales que vivían cerca o en Tham Nambrath.\n\nDe esta competitiva situación surgieron un buen número de historias de intriga, amor prohibido y toda clase de desatinos de la nobleza que han hecho las delicias del pueblo llano durante los siglos posteriores."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "12.10S"; 
          ["LONG"] = "63.86W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Ost Heryn"; 
      ["LORE"] = "Originalmente construida como una fortaleza para controlar el acceso a los Campos de Evendim desde el este, Ost Heryn se permitió languidecer durante los largos periodos de paz que caracterizaban a esas épocas. Finalmente fue comprada por una próspera familia de mercaderes y convertida en una lujosa finca. Por desgracia, el destino de Ost Heryn se torció en años posteriores, cuando surgieron amenazas imprevistas desde el Este y se convirtió en un suculento botín para salteadores y bandidos."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "11.20S"; 
          ["LONG"] = "61.32W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Tham Andalath"; 
      ["LORE"] = "Construida durante el apogeo de Annúminas y su influencia en el Norte, los dominios de Tham Andalath se convirtieron en los más extensos de los Campos de Evendim. Pronto fue conocido como un símbolo de extravagancia por eventos excesivamente suntuosos y su descarado tráfico de influencias entre las casas menores."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "9.57S"; 
          ["LONG"] = "63.23W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Tham Ornen"; 
      ["LORE"] = "La más pequeña de las grandes casas de Arnor construyó su palacio aquí, en Tham Ornen. Aunque no podían reclamar la riqueza o el poder de otras casas, se dice que esta famlia tenía estrechos lazos con el linaje real de los reyes de Annúminas. Como tales, sufrieron algunos de los más duros giros del destino que afectaron a muchas de las otras casas, y fueron muy respetados a lo largo de su larga historia.\n\nSin embargo, su destino estaba intrínsicamente entrelazado con el del linaje real así que cuando el poder de Arnor se dividió y apagó, el de la familia de Tham Ornen se desvaneció en las páginas de la historia."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "8.75S"; 
          ["LONG"] = "66.56W"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "Barad Rath"; 
      ["LORE"] = "Construido antes de la fundación original de Ost Forod, Barad Rath una vez delimitaba la frontera más al norte de la región del lago Evendim. Una vez que Ost Forod alcanzó la preeminencia en el norte, la importancia de Barad Rath entró en declive y se cree que se usaba como lugar de retiro ocasional para los miembros de la familia real cuando necesitaban encontrar paz y tranquilidad de las ajetreadas cortes de Annúminas o de su palacio en Tinnudir."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "7.31S"; 
          ["LONG"] = "66.62W"; 
        }; 
      }; 
      };
      [7] = {
      ["NAME"] = "Rantost"; 
      ["LORE"] = "Dadas las evidencias de las hermosas y extensas estructuras que antaño se erigieron en la isla de Rantost, es extraño que no se las mencionen en las historias de Arnor. Es posible que alguna familia poderosa buscando un estilo de vida más tranquilo y retirado lejos del caos continuo de la capital, eligieran construir su palacio aquí. Aún así, esa misma naturaleza ermitaña ha borrado cualquier mención de los cuentos e historias del Reino del Norte, y se han perdido para siempre en el tiempo."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "7.35S"; 
          ["LONG"] = "69.61W"; 
        }; 
      }; 
      };
      [8] = {
      ["NAME"] = "Tollobel"; 
      ["LORE"] = "Aisladas por el lago de la mayoría de otros dominios y ruinas de Evendim, pocos eruditos conocen a ciencia cierta la naturaleza de las ruinas que hoy se hallan aquí. Las principales teorías sugieren que una vez pudieron ser una prisión o almacén utilizado por los gobernantes de Annúminas. Esto al menos explicaría el secreto y las raras menciones del lugar en las historias de la región.\n\nPor desgracia, hay pocas pruebas sólidas que apoyen estas ideas, salvo por una serie de cámaras inusualmente profundas y extensas en las ruinas. Si hubiera cámaras en este lugar, haría mucho que hubieran sido despojadas de cualquier cosa de valor que contuvieran."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "11.38S"; 
          ["LONG"] = "71.95W"; 
        }; 
      }; 
      };
  };
  -- Evendim / Tierras salvajes de Evendim
  [1879089146] = {
      [1] = {
      ["NAME"] = "Nan Orngon"; 
      ["LORE"] = "Nan Orngon es una gran promontorio de piedra descubierto por los colonos originales de Evendim hace mucho. Aunque su posición, que domina los senderos hacia los Campos de Fornost, podría haberle otorgado cierta importancia, resultó imposible construir en sus escarpadas laderas incluso para los diestros canteros enanos de la época, y fue finalmente abandonada a la naturaleza salvaje."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "7.67S"; 
          ["LONG"] = "61.76W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Tûm Fuin"; 
      ["LORE"] = "El valle de Tûm Fuin y sus alrededores son conocidos por ser un lugar predilecto para cazadores y tramperos de Ost Forod. Se encuentra muy alejado de las rutas transitadas y cuenta con abundante fauna local. Sin embargo, apenas hay recursos o posibilidad de rescate para cualquier cazador que tenga la mala fortuna de resultar herido viajando tan lejos."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "4.38S"; 
          ["LONG"] = "65.24W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Los Saltos del Crepúsculo"; 
      ["LORE"] = "Los Saltos del Crepúsculo son una serie de estanques y caídas de agua conectados, alimentados por el deshielo de las montañas al norte del lago Evendim. Son tan fríos como el hielo incluso en los días más cálidos de verano, y se sabe que algunos rudos hombres del norte se desafían los unos a los otros a temerarias competiciones de resistencia para ver cuánto aguanta cada contendiente las temperaturas que hielan hasta los huesos de los estanques superiores."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "3.43S"; 
          ["LONG"] = "69.21W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Las Agujas de la Linde"; 
      ["LORE"] = "Pocos cazadores o tramperos llegan tan hacia el oeste de Ost Forod. Los relatos hablan de árboles que caminan y osos que construyen casas en estas remotas tierras salvajes. Aunque hay poco de verdad en la mayoría de estas historias, hay un cierto aura de extraña fantasía en la recóndita arboleda llamada las Agujas de la Linde..."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "6.09S"; 
          ["LONG"] = "71.96W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "La Laguna de la Linde"; 
      ["LORE"] = "La Laguna de la Linde representa el tramo inferior del mayor afluente del lago Evendim. Alimentada por rápidos que llegan desde la montaña y descienden en grandes caídas hacia el lago, la laguna es un lugar calmado y plácido que se decía era admirado por los viajeros que buscaban un remanso de paz en los antiguos días de Annúminas antes de que la ciudad fuera abandonada y mucho de las orillas lejanas de Evendim fueran reclamadas por la naturaleza salvaje."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "5.83S"; 
          ["LONG"] = "72.78W"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "Arroyo Veloz"; 
      ["LORE"] = "Este arroyo frío y aislado se interna profundamente en la roca de las montañas en lo alto del lado oeste del lago Evendim, antes de descender en tumultuosos rápidos a la Laguna de la Linde y de ahí al lago Evendim.\n\nLas leyenda shablan de una bella doncella quien, desconsolada por el abandono del hogar de sus antepasados y la invasión de la naturaleza salvaje sobre la antaño gloriosa ciudad de Annúminas vino aquí y se lanzó a las aguas desde las altas paredes del desfiladero.\n\nPor desgracia, ni siquiera las viejas historias alcanzan a vislumbrar la verdad de este relato, ni quién pudo haber sido aquella mujer."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "6.97S"; 
          ["LONG"] = "74.61W"; 
        }; 
      }; 
      };
      [7] = {
      ["NAME"] = "La Arboleda Maldita"; 
      ["LORE"] = "La Arboleda Maldita es un lugar oscuro e inquietante, que se encuentra en las tierras salvajes más hacia el oeste del lago Evendim. Incluso durante el reinado de los reyes de Arnor, era considerado un lugar que traía la mala suerte y era evitada por la mayoría. Ahora parece que ciertamente un poder malsano opera en este lugar, y los propios árboles parecen irradiar malicia hacia las criaturas vivientes que perturban su oscura soledad."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "10.93S"; 
          ["LONG"] = "74.86W"; 
        }; 
      }; 
      };
      [8] = {
      ["NAME"] = "Valcorriente"; 
      ["LORE"] = "Aunque no era visitada frecuentemente incluso en los tiempos de Arnor, el estanque conocido como Valcorriente era reverenciado por la gente local quien dejaba ofrendas flotantes en la orilla de sus aguas.\n\nA pesar del rugido de las cascadas cercanas, una sensación de calma reconfortante parece invadir tu espíritu mientras contemplas los reflejos cambiantes en el agua."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "13.75S"; 
          ["LONG"] = "75.84W"; 
        }; 
      }; 
      };
  };
