  -- Moria / La Gran Excavación
  [1879140051] = {
      [1] = {
      ["NAME"] = "Umbral de Durin"; 
      ["LORE"] = "El umbral de la puerta occidental de Khazad-dûm, fue aquí donde Durin completó su legendario viaje a través del corazón de las montañas y volvió a la luz del sol, habiendo descubierto el lugar que se convertiría en el hogar de su pueblo durante siglos."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "8.00S"; 
          ["LONG"] = "115.84W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Mirador de la Gran Excavación"; 
      ["LORE"] = "El Mirador de la Gran Excavación actúa como una ventana a la Gran Excavación de abajo. Desde aquí, antaño se podía ver a los enanos ir y venir, visitando los mercados, bibliotecas y talleres de esta caverna que alguna vez estuvo llena de vida. Ahora solo hay una vista larga y solitaria de fuegos de trasgos e insectos viles que se arrastran por la oscuridad."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "8.36S"; 
          ["LONG"] = "112.14W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "The Dwarf-lords' Gate"; 
      ["LORE"] = "Como la puerta norte de la Gran Excavación, la Puerta de los Señores Enanos es el paso principal para aquellos que buscan llegar al Camino de Durin."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "6.43S"; 
          ["LONG"] = "111.97W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "The Lonely Span"; 
      ["LORE"] = "Situada justo después de la puerta Este de la Gran Excavación, la Extensión Solitaria ofrece el único acceso directo a las calles de Zelem-melek, antiguo lugar de residencia de los nobles de Khazad-dûm."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "7.56S"; 
          ["LONG"] = "109.72W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "The Stone Council"; 
      ["LORE"] = "Las grandes esculturas en las paredes de esta antigua gruta representan al antiguo consejo de enanos que asesoraba a Durin y ayudaba en la administración diaria de Khazad-dûm. Muchas de estas grandes esculturas han sido dañadas por el tiempo y el desgaste, aunque afortunadamente el puente que atraviesa este espacio permanece intacto, aunque algo peligroso."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "9.00S"; 
          ["LONG"] = "112.09W"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "Gazatmur"; 
      ["LORE"] = "La gran plaza de Gazatmur, verdadero corazón de la Gran Excavación, estaba encuadrada por las más prestigiosas instituciones y los más magníficos monumentos de Khazad-dûm. Hoy, está ocupada por un vasto campamento trasgo, que impide a los enanos recuperar el control de la Excavación."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "7.61S"; 
          ["LONG"] = "111.39W"; 
        }; 
      }; 
      };
      [7] = {
      ["NAME"] = "Shemeldurj"; 
      ["LORE"] = "Shemeldurj era una finca inusual construida por un arquitecto excéntrico pero famoso de finales de la Segunda Edad. En un alejamiento del diseño clásico enano, presenta tramos y contrafuertes fantásticos que desafían al observador a buscar alrededor de cada giro y esquina para descubrir a dónde va a continuación. Gran parte de ella está en ruinas, arruinada por el tiempo y las manos devastadoras de los trasgos."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "1.50N"; 
          ["LONG"] = "128.21W"; 
        }; 
      }; 
      };
      [8] = {
      ["NAME"] = "The Palace of Náin"; 
      ["LORE"] = "Después de la caída de Durin, el terror se apoderó de los enanos de Moria, ahora dominados por el pánico y el miedo. El buen Náin tomó el lugar de su padre y se esforzó por sofocar la amenaza que amenazaba sus salas, deseando restaurar la paz a sus hermanos. Su corto reinado fue valiente, pero él también cayó ante el daño de Khazad-dûm."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "6.67S"; 
          ["LONG"] = "113.33W"; 
        }; 
      }; 
      };
  };
