  -- Raza y sociedad / Fortunas del Festival: Extrañamente Familiares
  [1879184300] = {
      [1] = {
        "Recoge la Fortuna -- 1 de 50 - 'Bah, eso solo habría sido un rasguño... ¡vuelve!'";
      };
      [2] = {
        "Recoge la Fortuna -- 2 de 50 - 'De verdad, tu corazón no conoce el miedo, hermano.'";
      };
      [3] = {
        "Recoge la Fortuna -- 3 de 50 - 'El tercer baile es este paso.'";
      };
      [4] = {
        "Recoge la Fortuna -- 4 de 50 - 'Ha habido una serie de pasteles podridos por toda la Comarca.'";
      };
      [5] = {
        "Recoge la Fortuna -- 5 de 50 - '¿Escuchaste eso, Wanetta? ¡Asphodel dijo que sí!'";
      };
      [6] = {
        "Recoge la Fortuna -- 6 de 50 - 'Tra la, tra la, tra lili, tra la. Rojo con sangre... donde la vida ha huido. Flores bonitas... tan rojas... La la, la lili, la la...'";
      };
      [7] = {
        "Recoge la Fortuna -- 7 de 50 - '¡Espero que el Último Príncipe venga pronto. ¡Tengo miedo!'";
      };
      [8] = {
        "Recoge la Fortuna -- 8 de 50 - Escuchas: '¡No es aquí! Dirígete al norte.'";
      };
      [9] = {
        "Recoge la Fortuna -- 9 de 50 - '¡Traigo terror a los corrales de Bolgovado! ¡Estos corrales son míos! Ja ja ja ja... ¡temed mi ira, Bolgers de Bolgovado!'";
      };
      [10] = {
        "Recoge la Fortuna -- 10 de 50 - '¿Estás tratando de matarte? ¡Sal del agua antes de ahogarte!'";
      };
  };
  -- Raza y sociedad / Fortunas del Festival: Fragmentos de un Narrador
  [1879184301] = {
      [1] = {
        "Recoge la Fortuna -- 11 de 50 - '¡Muchas gracias!'";
      };
      [2] = {
        "Recoge la Fortuna -- 12 de 50 - 'No conozco a la mitad de ustedes ni la mitad de bien que me gustaría; y me gusta menos de la mitad de ustedes ni la mitad de bien de lo que se merecen.'";
      };
      [3] = {
        "Recoge la Fortuna -- 13 de 50 - 'Es un asunto peligroso, salir por la puerta.'";
      };
      [4] = {
        "Recoge la Fortuna -- 14 de 50 - 'Pisas el Camino, y si no mantienes los pies, no se sabe a dónde te pueden llevar.'";
      };
      [5] = {
        "Recoge la Fortuna -- 15 de 50 - '¿Qué tengo en el bolsillo?'";
      };
      [6] = {
        "Recoge la Fortuna -- 16 de 50 - NO SE ADMITE EXCEPTO PARA ASUNTOS DE LA FIESTA";
      };
      [7] = {
        "Recoge la Fortuna -- 17 de 50 - 'Os he reunido a todos con un Propósito.'";
      };
      [8] = {
        "Recoge la Fortuna -- 18 de 50 - 'Haré lo que quiera e iré a donde me plazca.'";
      };
      [9] = {
        "Recoge la Fortuna -- 19 de 50 - 'El Sr. Bilbo Bolsón se ha ido; que yo sepa, para siempre.'";
      };
      [10] = {
        "Recoge la Fortuna -- 20 de 50 - 'Y vivió feliz para siempre, hasta el final de sus días.'";
      };
  };
  -- Raza y sociedad / Fortunas del Festival: Predicciones Fatídicas
  [1879184302] = {
      [1] = {
        "Recoge la Fortuna -- 21 de 50 - ¡Un viejo amor volverá a ti!";
      };
      [2] = {
        "Recoge la Fortuna -- 22 de 50 - Hoy tendrás una suerte maravillosa.";
      };
      [3] = {
        "Recoge la Fortuna -- 23 de 50 - Hoy tendrás una suerte terrible.";
      };
      [4] = {
        "Recoge la Fortuna -- 24 de 50 - ¡No puedes pasar!";
      };
      [5] = {
        "Recoge la Fortuna -- 25 de 50 - El fuego oscuro no te servirá de nada.";
      };
      [6] = {
        "Recoge la Fortuna -- 26 de 50 - Es hora de algunas heroicidades emocionantes.";
      };
      [7] = {
        "Recoge la Fortuna -- 27 de 50 - Todas las señales apuntan a quizás.";
      };
      [8] = {
        "Recoge la Fortuna -- 28 de 50 - ¡Deja de molestarme!";
      };
      [9] = {
        "Recoge la Fortuna -- 29 de 50 - Quizás deberías volver a preguntar más tarde.";
      };
      [10] = {
        "Recoge la Fortuna -- 30 de 50 - Respuesta confusa... mejor volver a intentarlo.";
      };
  };
  -- Raza y sociedad / Fortunas del Festival: Consejos Excelentes
  [1879184303] = {
      [1] = {
        "Recoge la Fortuna -- 31 de 50 - ¿Hambriento? Toma otra galleta.";
      };
      [2] = {
        "Recoge la Fortuna -- 32 de 50 - Cuidado con los agujeros muy profundos.";
      };
      [3] = {
        "Recoge la Fortuna -- 33 de 50 - Ten cuidado con los acantilados y los lugares altos, porque podrías sufrir grandes heridas si te caes.";
      };
      [4] = {
        "Recoge la Fortuna -- 34 de 50 - Cuidado con los Jinetes Negros.";
      };
      [5] = {
        "Recoge la Fortuna -- 35 de 50 - ¿Sediento? Tómate otra Porter de Perry.";
      };
      [6] = {
        "Recoge la Fortuna -- 36 de 50 - Deberías llevar comida contigo por si te da hambre.";
      };
      [7] = {
        "Recoge la Fortuna -- 37 de 50 - ¿Qué tal un poco de cuerda? La querrás, si no la tienes.";
      };
      [8] = {
        "Recoge la Fortuna -- 38 de 50 - Las sombras son más oscuras que la mayoría de los lugares, por lo que no podrás ver tanto cuando estés en ellas.";
      };
      [9] = {
        "Recoge la Fortuna -- 39 de 50 - ¡Mira siempre hacia arriba! Una rama de árbol podría caerte encima en cualquier momento. Pero mira por dónde caminas mientras tanto; no querrás tropezar.";
      };
      [10] = {
        "Recoge la Fortuna -- 40 de 50 - ¡Los jabalíes son feroces! Evítalos a toda costa. Especialmente los jabalíes de Evendim.";
      };
  };
  -- Raza y sociedad / Fortunas del Festival: La Canción de un Aventurero
  [1879184304] = {
      [1] = {
        "Recoge la Fortuna -- 41 de 50 - El camino sigue y sigue...";
      };
      [2] = {
        "Recoge la Fortuna -- 42 de 50 - ...Abajo desde la puerta donde comenzó...";
      };
      [3] = {
        "Recoge la Fortuna -- 43 de 50 - ...Ahora, muy adelante, el Camino se ha ido...";
      };
      [4] = {
        "Recoge la Fortuna -- 44 de 50 - ..Y debo seguir...";
      };
      [5] = {
        "Recoge la Fortuna -- 45 de 50 - ...si puedo.";
      };
      [6] = {
        "Recoge la Fortuna -- 46 de 50 - Persiguiéndola con pies ansiosos...";
      };
      [7] = {
        "Recoge la Fortuna -- 47 de 50 - ...Hasta que se une a un camino más grande...";
      };
      [8] = {
        "Recoge la Fortuna -- 48 de 50 - ...Donde muchos caminos y recados se encuentran...";
      };
      [9] = {
        "Recoge la Fortuna -- 49 de 50 - ¿...Y a dónde entonces...?";
      };
      [10] = {
        "Recoge la Fortuna -- 50 de 50 - ...No puedo decirlo.";
      };
  };
