  -- Rohan Oriental / East Wall Explorer
  [1879244108] = {
      [1] = {
      ["NAME"] = "Mansig's Encampment"; 
      ["PROGRESS"] = "Discover Mansig's Encampment"; 
      ["LORE"] = "This camp of Rohirrim hail primarily from the Wold, but there are representatives from throughout the kingdom of Rohan. They came to the East Wall under the command of Mansig. Their purpose was to investigate the fresh gathering of Orcs and Uruks that crossed the river, but they were ambushed upon arrival and still work to recover from that attack."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "52.06S"; 
          ["LONG"] = "51.28W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Claro del Orco Muerto"; 
      ["PROGRESS"] = "Descubre el Claro del Orco Muerto"; 
      ["LORE"] = "More than a dozen Orcs lie dead in a glade not far from Amon Hen. What happened here?"; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "56.64S"; 
          ["LONG"] = "49.78W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Parth Galen"; 
      ["PROGRESS"] = "Descubre Parth Galen"; 
      ["LORE"] = "The grassy lawn of Parth Galen would serve as a good location for the camp-site of any travellers forced to disembark the river, but it is in full view of the far shore and could be dangerous."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "58.59S"; 
          ["LONG"] = "47.94W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "The Tindrock"; 
      ["PROGRESS"] = "Discover the Tindrock"; 
      ["LORE"] = "The Tindrock is a great spur of rock that divides the waters of the Anduin as they rush towards the Falls of Rauros. Called Tol Brandir by the Elves, it is said to be unclimbable."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "59.20S"; 
          ["LONG"] = "46.02W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Falls of Rauros"; 
      ["PROGRESS"] = "Discover the Falls of Rauros"; 
      ["LORE"] = "The great Falls of Rauros descend from the cliffs with a booming roar. To follow the river over the edge means death."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "61.42S"; 
          ["LONG"] = "45.63W"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "Amon Hen"; 
      ["PROGRESS"] = "Discover Amon Hen"; 
      ["LORE"] = "Amon Hen is one of the two hills that rise on either side of the Anduin at the Falls of Rauros. The kings of old once sat upon the Seat of Seeing at its summit and saw many things of use to them."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "60.61S"; 
          ["LONG"] = "47.59W"; 
        }; 
      }; 
      };
      [7] = {
      ["NAME"] = "Sutcrofts Barricade"; 
      ["PROGRESS"] = "Discover the Sutcrofts Barricade"; 
      ["LORE"] = "The Orcs in the East Wall have erected a barricade to keep travellers from coming into the East Wall from the Sutcrofts."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "60.90S"; 
          ["LONG"] = "53.60W"; 
        }; 
      }; 
      };
      [8] = {
      ["NAME"] = "The North-guard"; 
      ["PROGRESS"] = "Discover the North-guard"; 
      ["LORE"] = "The North-guard is a chamber dominated by the Orcs of Moria in the tunnels beneath the East Wall."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "54.89S"; 
          ["LONG"] = "51.89W"; 
        }; 
      }; 
      };
      [9] = {
      ["NAME"] = "The Hissing Pit"; 
      ["PROGRESS"] = "Discover the Hissing Pit"; 
      ["LORE"] = "This chamber is full of gredbyg. It is possible other tunnels beneath the East Wall are infested with the creatures as well."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "55.46S"; 
          ["LONG"] = "51.95W"; 
        }; 
      }; 
      };
      [10] = {
      ["NAME"] = "The South-guard"; 
      ["PROGRESS"] = "Discover the South-guard"; 
      ["LORE"] = "This is the southernmost chamber of the tunnels beneath the East Wall, and it is full of Orcs from Moria."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "55.74S"; 
          ["LONG"] = "52.31W"; 
        }; 
      }; 
      };
  };
