      ["POINTS"] = {
        [1] = {
          ["LAT"] = "12.52S"; 
          ["LONG"] = "123.76W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "El Foso Oscuro"; 
      ["PROGRESS"] = "Discover the Black Pits"; 
      ["LORE"] = "The Mordath, the Black Pits of Mordor, is a place devoid of hope. It is the foundation of Barad-dûr, an ever-deepening mine, and a pit of punishment for those that have failed the Dark Lord. Those who are cast into the Black Pits will never again behold the light of Middle-earth."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "12.41S"; 
          ["LONG"] = "123.80W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Thol Shíkug, the Screaming Deep"; 
      ["PROGRESS"] = "Discover Thol Shíkug, the Screaming Deep"; 
      ["LORE"] = "Thol Shíkug is a fortress of terror and death built into the very foundations of Barad-dûr. For those condemned to the Black Pits, it is known as the Screaming Deep -- for many an Orc, Man, and beast have met their ends at the hands of the Dark Lord and his most powerful servants within. What lies within this grim structure, none have ever returned to tell."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "12.80S"; 
          ["LONG"] = "122.64W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Murpraush, the Hall of Spoiling"; 
      ["PROGRESS"] = "Discover Murpraush, the Hall of Spoiling"; 
      ["LORE"] = "Murpraush, the Hall of Spoiling, is where Sauron conducted the most vile of his sorceries. It was there he sought to equal the horrors of the first Dark Lord, Morgoth, and bring forth new and terrible creatures of his own imagining."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "12.62S"; 
          ["LONG"] = "122.73W"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "Glúrghash, The Pit of Flame"; 
      ["PROGRESS"] = "Discover Glúrghash, The Pit of Flame"; 
      ["LORE"] = "Glúrghash, The Pit of Flame, was once the prison of Thostír the Rank, a great fire-drake of the East. After devouring one of the Seven Rings, he was captured by agents of Mordor and imprisoned beneath Barad-dûr. However, when the Mordath was split asunder, he flew from its shadowed depths and escaped the Land of Shadow."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "13.96S"; 
          ["LONG"] = "123.64W"; 
        }; 
      }; 
      };
      [7] = {
      ["NAME"] = "Glúrakul, The Pit of Frost"; 
      ["PROGRESS"] = "Discover Glúrakul, The Pit of Frost"; 
      ["LORE"] = "Glúrakul, The Pit of Frost, was once home to Hrímil Frost-heart, a cold-drake of the Grey Mountains. After Hrímil came to the dwarf-halls in the East and devoured one of the Seven Rings, she was captured and imprisoned beneath the Dark Tower. However, when Barad-dûr fell and the Mordath was shattered, she flew from her prison and escaped from Mordor."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "14.30S"; 
          ["LONG"] = "123.77W"; 
        }; 
      }; 
      };
      [8] = {
      ["NAME"] = "Glurnákh, The Pit of Greed"; 
      ["PROGRESS"] = "Discover Glurnákh, The Pit of Greed"; 
      ["LORE"] = "Glurnákh, The Pit of Greed, has long been the home to Fingar the Greedy, an ancient Worm of Angband. After devouring two of the Seven Rings, Fingar was captured and imprisoned beneath the Dark Tower to suffer evermore."; 
      ["POINTS"] = {
        [1] = {
