  -- Imlad Morgul / Scouting Minas Morgul
  [1879395353] = {
      [1] = {
      ["NAME"] = "Barad Angarth, la fortaleza de los guardianes de la puerta"; 
      ["PROGRESS"] = "Explore Barad Angarth, the Gate-wardens' Keep"; 
      ["LORE"] = "Barad Angarth has been reclaimed from the Orcs, and now it serves the White Company as a foothold in the city. Further such towers may better serve the reclamation, but they will first need to be taken from the foes that hold them."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "24.97S"; 
          ["LONG"] = "19.26E"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Barad Orhant, la Torre del Patio del Árbol"; 
      ["PROGRESS"] = "Explore Barad Orhant, the Tower of the Treegarth"; 
      ["LORE"] = "Barad Orhant once overlooked the Circle of Skill in Minas Ithil, but now the view has changed. That tier is now the Circle of Sorrow, and it is home only to the Dead. So too was the Tower of the Treegarth, but it has been seized for the use of the White Company. Perhaps it will be the same for the Circle of Sorrow."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "26.45S"; 
          ["LONG"] = "19.16E"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Barad Elenath, la Torre de Observación Estelar"; 
      ["PROGRESS"] = "Explore Barad Elenath, the Star-gazers' Spire"; 
      ["LORE"] = "Barad Elenath, the Star-gazers' Spire, was once a place of study and learning. From its great height the scholars of the city spent night after night studying the moon and the stars, but that was long ago. The merrevail of Lhaereth the Stained claimed this tower, and have only just been driven away. The tower serves now as a foothold for the White Company's reclamation of Minas Morgul."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "25.19S"; 
          ["LONG"] = "19.31E"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Barad Arthir, la alta fortaleza de vigilancia"; 
      ["PROGRESS"] = "Explore Barad Arthir, the Lofty Watch-fort"; 
      ["LORE"] = "The Circle of Mirth above which stood Barad Arthir has become the Circle of Despair, haunted by spirits and a place of great danger for Faramir's White Company, which seeks to restore the city. That goal remains far-off, but every step taken is a step closer, and with the spirits driven out of Barad Arthir, perhaps more victories will soon follow."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "26.60S"; 
          ["LONG"] = "19.56E"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Song-house of Lindalírë"; 
      ["PROGRESS"] = "Explore the Song-house of Lindalírë"; 
      ["LORE"] = "Minstrels and poets flocked to Minas Ithil when Gondor was at its height, and the lamps were lit in the Song-house of Lindalírë long into the night. But the Night proved darker and more insidious, and with the coming of the Witch-king the theatre is host only to the Dead."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "67.11S"; 
          ["LONG"] = "3.14E"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "Roz Dagalur, the Fiend-house"; 
      ["PROGRESS"] = "Explore Roz Dagalur, the Fiend-house"; 
      ["LORE"] = "The gauntmen walk in Roz Dagalur, and few only know the way inside. Fewer still know the way out."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "5.77S"; 
          ["LONG"] = "28.54E"; 
        }; 
      }; 
      };
      [7] = {
      ["NAME"] = "Búrzangh, the Shrouded Forge"; 
      ["PROGRESS"] = "Explore Búrzangh, the Shrouded Forge"; 
      ["LORE"] = "They say the forge works still, but the hands of men touch it not. In Búrzangh some ghostly power takes command, seeking to craft some relic of ancient days, but none among the living can say what artifact the spirits desire to create."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "55.73N"; 
          ["LONG"] = "54.80E"; 
        }; 
      }; 
      };
      [8] = {
      ["NAME"] = "Dâr Grazadh, the Hall of Rot"; 
      ["PROGRESS"] = "Explore Dâr Grazadh, the Hall of Rot"; 
      ["LORE"] = "The smell of decaying flesh fills the Hall of Rot, and wights stalk among chambers once home to light and life. But those days are gone, and King Elessar is uncertain if they can ever return."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "57.81N"; 
          ["LONG"] = "54.80E"; 
        }; 
      }; 
      };
      [9] = {
      ["NAME"] = "Ghashan-kútot, los Salones del Saber Oscuro"; 
      ["PROGRESS"] = "Explore Ghashan-kútot, the Hall of Black Lore"; 
      ["LORE"] = "The dusty paths between the shelves of Ghashan-kútot are walked by an unnatural force. It answers to the name Dolguzigir, but few only have seen the Accursed Sage. It is said he can drape himself in whatever form he wishes, but he is not a Man, and if he appears so it is only in answer to his whim. He is eager to learn the story of any who stray into the Hall of Black Lore, eager almost to the point of sickness, and he does not wish for any to leave... uncollected."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "68.01S"; 
          ["LONG"] = "0.71E"; 
        }; 
      }; 
      };
      [10] = {
      ["NAME"] = "Aguas Siniestras"; 
      ["PROGRESS"] = "Explora las Aguas Siniestras"; 
      ["LORE"] = "The baths of Minas Ithil were once a place to rest and relax, and the people who lived here scrubbed away the dirt and the grime of their daily lives, sinking into waters of contentment. Now the baths are empty of all good folk, haunted by shades of evil."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "67.23S"; 
          ["LONG"] = "2.39E"; 
        }; 
      }; 
      };
      [11] = {
      ["NAME"] = "The Garth of Angáth"; 
      ["PROGRESS"] = "Explore the Garth of Angáth"; 
      ["LORE"] = "'Is there anything more sad to the heart than a garden dead and twisted? So it was with Ithilien, and already we work to restore my land's beauty. Perhaps it can be the same here.' - Prince Faramir"; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "66.83S"; 
          ["LONG"] = "1.43E"; 
        }; 
      }; 
      };
      [12] = {
      ["NAME"] = "Bâr Maenath"; 
      ["PROGRESS"] = "Explore Bâr Maenath"; 
      ["LORE"] = "Most of Minas Ithil's treasures were already looted, either by good folk fleeing from the city in advance of its several falls, or by forces of evil in search of artifacts and gold. The relics that remain have been corrupted by the long residence of the Nazgûl and their minions, and now Bâr Maenath holds only ill fortune for the few treasure-seekers who dare explore there."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "12.29S"; 
          ["LONG"] = "28.71E"; 
        }; 
      }; 
      };
      [13] = {
      ["NAME"] = "Uialrond, the Dome of Evening"; 
      ["PROGRESS"] = "Explore Uialrond, the Dome of Evening"; 
      ["LORE"] = "The Dome of Evening has been sealed away for years uncounted, and for purpose unknown."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "67.41S"; 
          ["LONG"] = "1.58E"; 
        }; 
      }; 
      };
      [14] = {
      ["NAME"] = "The Wracking-hall"; 
      ["PROGRESS"] = "Explore the Wracking-hall"; 
      ["LORE"] = "Once a place of feasting and good cheer, the Wracking-hall has not known a meal free of terror for countless years. Now it is a den of evil, and only horrors sup there."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "39.03S"; 
          ["LONG"] = "15.70E"; 
        }; 
      }; 
      };
      [15] = {
      ["NAME"] = "Gath Daeroval"; 
      ["PROGRESS"] = "Explore Gath Daeroval"; 
      ["LORE"] = "The Shadow-roost of Gath Daeroval is home to Khatlob, the great brood-mother who birthed the vile flying mounts used by the Nazgûl in pursuit of the aims of Sauron."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "67.82S"; 
          ["LONG"] = "2.55E"; 
        }; 
      }; 
      };
      [16] = {
      ["NAME"] = "Barad Cúron, the Tower of the Crescent Moon"; 
      ["PROGRESS"] = "Explore Barad Cúron, the Tower of the Crescent Moon"; 
      ["LORE"] = "Barad Cúron rises from the top of the city, a place of mystery much-coveted by each of the Masters of Mordor."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "67.79S"; 
          ["LONG"] = "1.81E"; 
        }; 
      }; 
      };
      [17] = {
      ["NAME"] = "Zhar Dushgoi"; 
      ["PROGRESS"] = "Explore Zhar Dushgoi"; 
      ["LORE"] = "The sprawling encampment of Zhar Dushgoi was established by Gothmog's Orcs who gather what defenses they can to hold the Circle of Wrath from Ugrukhôr's forces."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "66.16S"; 
          ["LONG"] = "2.56E"; 
        }; 
      }; 
      };
      [18] = {
      ["NAME"] = "Zhar Skator"; 
      ["PROGRESS"] = "Explore Zhar Skator"; 
      ["LORE"] = "Ugrukhôr's forces have pushed into Minas Morgul and established the encampment of Zhar Skator upon the Circle of Wrath."; 
      ["POINTS"] = {
