  -- Tierras de Bree / Flores del Bosque Salvaje
  [1879414498] = {
      [1] = {
      ["NAME"] = "Eufrasia"; 
      ["PROGRESS"] = "Encuentra eufrasia"; 
      ["LORE"] = "Se dice que esta encantadora y pequeña planta puede hacer de todo, desde difundir alegría hasta curar dolencias oculares. Algunos rumores dicen que un tónico de eufrasia aplicado en el ojo antes de acostarse concede sueños proféticos."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "22.55S"; 
          ["LONG"] = "58.09W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Robin andrajoso"; 
      ["PROGRESS"] = "Encuentra clavelina de prado"; 
      ["LORE"] = "Las leyendas dicen que alguien que lleve esta flor rosada y desgreñada en la solapa encontrará pronto el amor. Es normal verlas rodeadas de mariposas, que sienten una profunda predilección por la clavelina de prado."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "23.63S"; 
          ["LONG"] = "63.52W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Cardencha"; 
      ["PROGRESS"] = "Encuentra cardo"; 
      ["LORE"] = "Muy apreciadas por los sastres, las espinas del cardo se utilizan para cardar telas, especialmente lana. Se dice que el agua que se almacena en los pequeños recipientes que se forman alrededor del tallo revierte los signos de envejecimiento cuando se aplica sobre la piel."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "21.78S"; 
          ["LONG"] = "60.05W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Verónica"; 
      ["PROGRESS"] = "Encuentra verónica"; 
      ["LORE"] = "Pequeña y delicada, la verónica sirve para preparar un buen té, pero no para moverse más rápido, como sugieren a menudo los rumores. Sin embargo, puede aliviar a quienes sufren de lepra o gota."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "21.38S"; 
          ["LONG"] = "56.17W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Bolsa de pastor"; 
      ["PROGRESS"] = "Encuentra bolsa de pastor"; 
      ["LORE"] = "Una planta versátil que tiene usos tanto medicinales como culinarios, la bolsa de pastor a menudo se confunde con una mala hierba. Aunque sus propiedades curativas abarcan numerosas dolencias, se cree que la bolsa de pastor también es beneficiosa para tratar una gran cantidad de problemas sanguíneos."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "18.66S"; 
          ["LONG"] = "57.58W"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "Euforbia de madera"; 
      ["PROGRESS"] = "Encuentra euforbia silvestre"; 
      ["LORE"] = "Con sus hojas coriáceas de color verde oscuro y sus flores de un amarillo brillante, la euforbia silvestre es una encantadora planta tapizante. Sin embargo, al cortarla, la planta segrega un líquido lechoso blanco que puede causar dolor e irritación en la piel."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "17.18S"; 
          ["LONG"] = "55.40W"; 
        }; 
      }; 
      };
      [7] = {
      ["NAME"] = "Sonajero amarillo"; 
      ["PROGRESS"] = "Encuentra campanilla amarilla"; 
      ["LORE"] = "Hacia el final del verano, las vainas de semillas de la campanilla amarilla se convierten en cáscaras secas, finas como el papel. El sonido que produce el viento al soplar y hacer vibrar las semillas en su interior es la razón por la que esta vivaz planta recibió su nombre."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "17.98S"; 
          ["LONG"] = "60.04W"; 
        }; 
      }; 
      };
      [8] = {
      ["NAME"] = "Cardo anudado"; 
      ["PROGRESS"] = "Encuentra cardo nudoso"; 
      ["LORE"] = "A veces mirada con muecas o pisoteada, detrás de las púas en forma de aguja el tallo del cardo nudoso puede hervirse y usarse en tartas como el ruibardo. Sin embargo, sobre sus flores se cuenta que las utilizan los vecinos celosos para cortar la leche."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "15.94S"; 
          ["LONG"] = "58.73W"; 
        }; 
      }; 
      };
  };
