  -- Gundabad / Sites of Deepscrave
  [1879424673] = {
      [1] = {
      ["NAME"] = "Aslíf"; 
      ["PROGRESS"] = "Explore Aslíf"; 
      ["LORE"] = "Amidst the unfriendly dark of Deepscrave, the Gabil'akkâ have eked out a small place of respite. Aslíf clings to the Berg-beam, as if it is in danger of disappearing into the shadows that surround it."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "50.12S"; 
          ["LONG"] = "117.31W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Buzra-salân"; 
      ["PROGRESS"] = "Explore Buzra-salân"; 
      ["LORE"] = "A waterfall that spills into the depths of Deepscrave. The dwarf-homes that cluster around Buzra-salân are mostly intact, as Orcs have claimed these homes for their own."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "47.33S"; 
          ["LONG"] = "117.46W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Gabil-memâg"; 
      ["PROGRESS"] = "Explore Gabil-memâg"; 
      ["LORE"] = "Water from the adjacent Gloomingtarn pours onto the ancient water-wheels at Gabil-memâg. During brighter days, the water-wheels powered the lifts of Deepscrave. Now they serve little purpose, cycling endlessly through the ages."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "49.8S"; 
          ["LONG"] = "119.38W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "'Abad-nuhbu, the Berg-beam"; 
      ["PROGRESS"] = "Explore 'Abad-nuhbu, the Berg-beam"; 
      ["LORE"] = "Sometimes referred to as the Pillar of the Mountain, the Berg-beam almost seems to hold the entire cavern ceiling aloft. It was here that most of the common folk of Gundabad built their homes."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "50.31S"; 
          ["LONG"] = "117.39W"; 
        }; 
      }; 
      };
  };
