  -- Gundabad / Enemies of Deepscrave
  [1879424790] = {
      [1] = {
      ["NAME"] = "Kordh Gúrat"; 
      ["PROGRESS"] = "Explore Kordh Gúrat"; 
      ["LORE"] = "Orcs weren't the only ones who moved into Deepscrave once the dwarves were driven out. Drakes found comfort within the darkness and made a new home for themselves."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "51.61S"; 
          ["LONG"] = "118.63W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Durshulot"; 
      ["PROGRESS"] = "Explore Durshulot"; 
      ["LORE"] = "After Gorgar fled to Deepscrave, he dwelled in Durshulot for a while, but did not stay for long. A mixture of paranoia and distrust prompted him to find a better stronghold from which to rule."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "49.20S"; 
          ["LONG"] = "118.11W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Gazat-fark"; 
      ["PROGRESS"] = "Explore Gazat-fark"; 
      ["LORE"] = "During the days of old, the dwarf-smiths produced magnificent creations in Gazat-fark. Now, the smithy only sees use in times of war."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "51.12S"; 
          ["LONG"] = "115.72W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Durbángh"; 
      ["PROGRESS"] = "Explore Durbángh"; 
      ["LORE"] = "To sate their ever-growing need for weapons and armour, the Orcs rely on Durbángh's mighty forges. The intense heat inside Durbángh never abates."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "51.27S"; 
          ["LONG"] = "115.46W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Dalugronk"; 
      ["PROGRESS"] = "Explore Dalugronk"; 
      ["LORE"] = "In an attempt to combat the hostile worms nearby, the Orcs of Dalugronk have begun experimenting with bat-riding. This has been met with varying degrees of failure."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "48.84S"; 
          ["LONG"] = "116.27W"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "Vatug-ronk, the Groaning Pit"; 
      ["PROGRESS"] = "Explore Vatug-ronk, the Groaning Pit"; 
      ["LORE"] = "Broken dwarf-machinery groans incessantly throughout Deepscrave, but the noise is loudest in Vatug-ronk. It is the largest Orc-settlement in Deepscrave, as well as home to the most foul-tempered of Orcs."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "50.55S"; 
          ["LONG"] = "119.09W"; 
        }; 
      }; 
      };
      [7] = {
      ["NAME"] = "Shataz-kordh"; 
      ["PROGRESS"] = "Explore Shataz-kordh"; 
      ["LORE"] = "Formerly part of Dalugronk, Shataz-kordh now plays host to worms instead of Orcs. The Orc corpses that litter the area have proven to be effective at keeping the denizens of Dalugronk away."; 
      ["POINTS"] = {
        [1] = {
