  -- Bosque de los Trolls / Sitios del Ángulo
  [1879443654] = {
      [1] = {
      ["NAME"] = "Cabaña del Helechal"; 
      ["PROGRESS"] = "Explora la Cabaña del Helechal"; 
      ["LORE"] = "Cabaña del Helechal es el hogar pacífico e idílico de Maddoc y Glenys Astaciervo, una familia de leñadores que llegó a vivir al Ángulo hace algunos años. Ahora se ganan la vida recolectando la resistente madera del Mitheithel, además de vender pequeñas tallas de madera, oficio de Glenys. Su hijo Bran explora los bosques cercanos, metiéndose a menudo en problemas propios, aunque hasta ahora siempre ha logrado salir por sí mismo, algo de lo que su padre habla con orgullo a todo aquel que encuentra."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "39.40S"; 
          ["LONG"] = "17.38W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Tham Lumren"; 
      ["PROGRESS"] = "Explora Tham Lumren"; 
      ["LORE"] = "Los árboles que antaño dieron abrigo y cobertura a Tham Lumren, el salón sombrío, murieron hace mucho tiempo durante la Guerra de los Elfos y Sauron y jamás fueron replantados. Aun así, los Elfos han regresado a estas ruinas y quizá restauren los árboles antes de partir, si así lo desean."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "38.68S"; 
          ["LONG"] = "17.33W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Gaerond"; 
      ["PROGRESS"] = "Explora Gaerond"; 
      ["LORE"] = "Las ruinas ahuecadas de Gaerond son ahora el hogar de exploradores enviados por los hijos de Elrond, quienes viajan hacia el sur de vez en cuando para vigilar el Ángulo deL Mitheithel. No son los únicos viajeros que últimamente llegan desde el Bosque de los Trolls: trolls, bandidos y criaturas de índole más peligrosa han sido conocidos por amenazar la seguridad de esta tierra."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "34.73S"; 
          ["LONG"] = "22.12W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Refugio de los Cuan-lûth"; 
      ["PROGRESS"] = "Explora el refugio de los Cuan-lûth"; 
      ["LORE"] = "Antiguamente un refugio utilizado por los Montaraces de Tornhad, esta cueva ahora alberga a refugiados de Cuan-lûth que se niegan a inclinarse ante Saruman."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "41.79S"; 
          ["LONG"] = "23.39W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Tornhad"; 
      ["PROGRESS"] = "Explora Tornhad"; 
      ["LORE"] = "El pueblo de Tornhad, ubicado al fondo de una garganta boscosa formada por un río en el Ángulo y no lejos de Thelgarth, es el asentamiento principal de los Montaraces en la región. A diferencia de otros campamentos de los Dúnedain, Tornhad ha logrado mantenerse como un asentamiento más o menos permanente, principalmente debido a su capacidad de refugiarse en cuevas de las colinas cuando el peligro parece aproximarse.\n\nEn tiempos de paz, Tornhad es hogar de muchas familias de Montaraces, y los niños aprenden sus métodos de supervivencia desde muy pequeños; algunos incluso son acogidos en Rivendel, donde reciben instrucción en historia, arte y artesanía. Con la guerra asomándose en el horizonte, muchas de las mujeres y los niños dúnedain ya se han trasladado a la seguridad de sus cuevas ocultas, mientras que otros toman las armas y patrullan las tierras salvajes, manteniendo los caminos despejados por orden de Aragorn."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "42.99S"; 
          ["LONG"] = "23.51W"; 
        }; 
      }; 
      };
  };
  -- Bosque de los Trolls / Enemigos del Ángulo
  [1879443655] = {
      [1] = {
      ["NAME"] = "Eitheldir"; 
      ["PROGRESS"] = "Explora Eitheldir"; 
      ["LORE"] = "La fortaleza de Eitheldir, la Atalaya del Pozo, fue construida sobre los vados del Fontegrís para proteger el paso hacia Lindon durante la Segunda Edad. Sin embargo, la propia fortaleza sería el escenario de una dolorosa derrota durante la Guerra de los Elfos y Sauron, cuando la intrépida capitana Oranoril atrajo a los ejércitos de Sauron hacia la fortificación, donde ella y su compañía encontraron la muerte.\n\nY aun así, el sacrificio de Oranoril no es recordado como una derrota, pues gracias a sus acciones y a las de sus guerreros escogidos, muchos de los Eldar pudieron huir hacia el recién fundado refugio de Imladris, en las Montañas Nubladas, donde sobrevivieron a las atrocidades de Sauron y se reagruparon para el contraataque que finalmente llevaría a su caída temporal."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "36.19S"; 
          ["LONG"] = "22.61W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Glynafon"; 
      ["PROGRESS"] = "Explora Glynafon"; 
      ["LORE"] = "Mil años después del comienzo de la Tercera Edad, una rama de los hól-budlan que se hacía llamar los Stôrs cruzó las montañas en busca de un lugar hospitalario donde vivir. Fundaron el asentamiento de Glynafon, que se convirtió en hogar de numerosas granjas prósperas entre las rocas y los árboles del Ángulo.\n\nLos Stôrs vivieron pacíficamente en Glynafon durante unos trescientos años, pero debido a la agitación en Rhudaur y la creciente amenaza del joven reino de Angmar, gobernado por el Rey Brujo, se vieron obligados a abandonar el Ángulo en busca de nuevas tierras."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "39.97S"; 
          ["LONG"] = "18.37W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Ost Waeren"; 
      ["PROGRESS"] = "Explora Ost Waeren"; 
      ["LORE"] = "Los bosques del Bosque de los Trolls y del Ángulo están llenos de ruinas del pequeño reino de Rhudaur, una provincia asediada tanto por los trolls del Bosque de los Trolls como por los Amonedain que vivían en el Ángulo antes de la llegada de los Dúnedain. Rhudaur acabaría sucumbiendo a la presión externa y a la traición interna, y el Ángulo se convertiría en una tierra fronteriza, una zona limítrofe llamada por algunos Harnaith, el punto del sur, y por otros una naturaleza indómita que era mejor dejar a trolls y montañeses.\n\nCualesquiera actos atroces que se cometieran en Ost Waeren por mandato de los siervos del Rey Brujo han sido afortunadamente olvidados por los Hombres, pero las piedras vigilantes y la tierra empapada de sangre aún recuerdan."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "38.39S"; 
          ["LONG"] = "22.32W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Thelgarth"; 
      ["PROGRESS"] = "Explora Thelgarth"; 
      ["LORE"] = "La fortaleza de Thelgarth estaba siendo construida cuando Sauron emergió para atacar Gondor, encendiendo la Guerra de la Última Alianza. Cuando los supervivientes regresaron algunos años después, los Amonedain que habían luchado junto a los Pueblos Libres recibieron permiso para permanecer en el Ángulo. Ayudaron a terminar la construcción de Thelgarth, que se convirtió en un baluarte contra un ataque desde el sur que nunca llegó.\n\nLa amenaza acabaría viniendo del norte, cuando el reino de Arnor se fragmentó en tres pequeños reinos: Arthedain, Cardolan y Rhudaur. Cuando este último cayó bajo la corrupción del Rey Brujo, la ciudadela de Thelgarth resistió más que ninguna otra, sirviendo como asiento de sus reyes dúnedain supervivientes incluso ante el creciente mal de Angmar. Cuando el Rey de Rhudaur y toda su casa, salvo una persona, fueron asesinados por orden del Rey Brujo, la última princesa de Rhudaur se refugió en secreto en Thelgarth.\n\nPero la peste y el poder creciente de Angmar sellaron la perdición de los Dúnedain. En el año 1637, cultistas angmarim derribaron los muros de Thelgarth y masacraron a sus defensores en una matanza que se conocería como la Noche de las Aguas Rojas. El Ángulo permaneció desolado durante cientos de años, hasta que con el tiempo semiorcos y bandidos se infiltraron en las ruinas abandonadas de Thelgarth, ajenos a su larga y turbulenta historia."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "44.54S"; 
          ["LONG"] = "22.90W"; 
        }; 
      }; 
      };
  };
