  -- la Ciénaga de los Cisnes y Cardolan / Peligros de la Ciénaga de los Cisnes
  [1879450861] = {
      [1] = {
      ["NAME"] = "Piedras Aullantes"; 
      ["PROGRESS"] = "Encuentra las Piedras Aullantes"; 
      ["LORE"] = "Los lobos han vivido en las Piedras Aullantes desde que el pueblo de Musgovilla tiene memoria, pero por lo general no se acercaban demasiado a la empalizada exterior. Eso ha cambiado en las últimas noches: los guardias de la ciudad han visto ojos lupinos observándolos desde la oscuridad con inquietante frecuencia."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "61.31S"; 
          ["LONG"] = "33.38W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Radlaw"; 
      ["PROGRESS"] = "Encuentra Radlaw"; 
      ["LORE"] = "Nadie sabe con certeza cuándo llegaron los rufianes a la Ciénaga de los Cisnes, pero para los Fuertes, el asentamiento proscrito de Radlaw pareció surgir de la noche a la mañana. Ahora no es seguro para la mayoría recorrer los Valles de los Fuertes sin cuidado, pues los rufianes de Radlaw siempre están atentos para robar monedas u objetos valiosos a los incautos."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "59.73S"; 
          ["LONG"] = "29.29W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Fangsettle"; 
      ["PROGRESS"] = "Encuentra Colmillar"; 
      ["LORE"] = "El Aguaestancada está lleno de peligros, pero pocos lugares del pantano son tan amenazadores como Colmillar, donde los avanc construyen sus nidos. Solo los dunlendinos de la cercana Lhan Garan se aventuran cómodamente en esta zona de cría, y aun así sus mejores exploradores intentan no acercarse demasiado sin necesidad urgente."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "54.73S"; 
          ["LONG"] = "30.46W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Cuencasangre"; 
      ["PROGRESS"] = "Encuentra la Cuencasangre"; 
      ["LORE"] = "Montones de huesos desechados y las carcasas de presas muertas hace tiempo marcan las guaridas de los huargos en la Cuencasangre, un lugar tan peligroso que incluso los más habilidosos guerreros dunlendinos de Lhan Garan intentan evitarlo salvo en extrema necesidad. Pero a veces surge tal necesidad: el entrenamiento de nuevos exploradores exige ponerlos a prueba frente a circunstancias peligrosas y enemigos amenazantes, y ¿qué prueba mejor que los huargos que acechan la Cuencasangre?"; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "56.83S"; 
          ["LONG"] = "21.63W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Hondonada del Terrón"; 
      ["PROGRESS"] = "Encuentra Hondonada del Terrón"; 
      ["LORE"] = "Las arañas tejedoras que habitan Hondonada del Terrón no toleran ninguna intrusión de los Fuertes que viven cerca, pero los habitantes de Glyn Helyg y Clegur aprendieron hace mucho a no internarse bajo los árboles cubiertos de telarañas, y la gente de Lintrev no suele alejarse de sus propias granjas."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "65.49S"; 
          ["LONG"] = "26.09W"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "Sharmokal"; 
      ["PROGRESS"] = "Encuentra Sharmokal"; 
      ["LORE"] = "Una partida de incursión uruk ha establecido un campamento no muy lejos del Viejo Camino del Sur, donde se alzan los restos de una torre élfica. ¿Para qué se construyó esta torre en una Edad pasada? Los uruks lo ignoran, y los Elfos que podrían recordarlo prefieren no decirlo. Ahora el lugar es Sharmokal, y no es seguro que los viajeros se acerquen demasiado."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "60.39S"; 
          ["LONG"] = "22.32W"; 
        }; 
      }; 
      };
      [7] = {
      ["NAME"] = "Caras Gelebren"; 
      ["PROGRESS"] = "Encuentra Caras Gelebren"; 
      ["LORE"] = "El gran herrero élfico Celebrimbor construyó la ciudad donde forjaría su legado en la confluencia de los ríos Sirannon y Glanduin. Caras Gelebren, el Bastión de Plata, fue un lugar de belleza y aprendizaje durante gran parte de la Segunda Edad, pero la dicha no perduró. Bajo un bello disfraz, el mal llegó a Caras Gelebren, y Celebrimbor fue engañado. Atrapado por su orgullo y su ansia de conocimiento secreto, el herrero élfico estuvo a punto de quebrar el mundo.\n\nCuando Sauron trajo la guerra a Eregion tras el desatino de Celebrimbor, la ciudadela fue destruida y todo recuerdo de sus días pacíficos quedó olvidado. Aun habría triunfos en los años venideros, pero en el fondo los Elfos recuerdan la vergüenza sobre la que se asentó todo, y lloran."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "53.62S"; 
          ["LONG"] = "20.92W"; 
        }; 
      }; 
      };
      [8] = {
      ["NAME"] = "Tham Lasgol"; 
      ["PROGRESS"] = "Encuentra Tham Lasgol"; 
      ["LORE"] = "Los árboles han reclamado Tham Lasgol. Los Elfos no habrían lamentado tal destino, pero algo ha atraído a los trolls silvanos a este lugar antaño hermoso, y ahora se ha convertido en un sitio peligroso."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "49.30S"; 
          ["LONG"] = "23.79W"; 
        }; 
      }; 
      };
      [9] = {
      ["NAME"] = "Gwâl Cruban"; 
      ["PROGRESS"] = "Encuentra Gwâl Cruban"; 
      ["LORE"] = "Los edificios que una vez se alzaron aquí están ahora cubiertos por juncos, y solo son visitados por tortugas."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "51.95S"; 
          ["LONG"] = "26.14W"; 
        }; 
      }; 
      };
      [10] = {
      ["NAME"] = "Tham Celechir"; 
      ["PROGRESS"] = "Encuentra Tham Celechir"; 
      ["LORE"] = "Tham Celechir, el Salón del Río Veloz, fue uno de los últimos lugares en resistir a los ejércitos de Sauron cuando llevó la guerra a Eregion en la Segunda Edad. Muchos Elfos murieron dentro y fuera de sus muros, y las huellas de su última resistencia aún pueden verse entre los restos que pueblan esta antigua y orgullosa ruina."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "45.56S"; 
          ["LONG"] = "19.45W"; 
        }; 
      }; 
      };
  };
