  [1879450862] = {
      [1] = {
      ["NAME"] = "Piedra angular"; 
      ["PROGRESS"] = "Descubre una vieja piedra angular"; 
      ["LORE"] = "Estas viejas piedras pueden haber sido testigo del ataque de Sauron, pero aún se aferran a recuerdos más felices. Bodas, centenarios personales y ceremonias de todo tipo tuvieron lugar en este pabellón antaño elegante."; 
