  -- la Ciénaga de los Cisnes y Cardolan / Peligros de Cardolan
  [1879450925] = {
      [1] = {
      ["NAME"] = "Amon Firn"; 
      ["PROGRESS"] = "Explorar Amon Firn"; 
      ["LORE"] = "La masacre de la Batalla de Amon Firn fue tan intensa que la colina pasó a ser conocida como el Monte de los Muertos. Se erigió un gran túmulo en memoria de los caídos.\n\nFue aquí donde el último rey dúnadan de Cardolan, Artandil, mató y fue muerto por el Rey Malgun I de Rhudaur. Desde entonces, flores rojas florecen aquí."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "44.32S"; 
          ["LONG"] = "29.15W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Caranost"; 
      ["PROGRESS"] = "Explorar Caranost"; 
      ["LORE"] = "Antaño una gran ciudad de Arnor y sede de príncipes, Caranost también era conocida como el Fuerte Rojo. Fue saqueada por Angmar durante el declive de Cardolan.\n\nLas torres de Caranost dominaban una amplia vista de una gran extensión de la región norte de Cardolan, pero cuando la ciudad fue tomada, muchas de las torres fueron destruidas."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "45.17S"; 
          ["LONG"] = "40.65W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Dol Ernil"; 
      ["PROGRESS"] = "Explorar Dol Ernil"; 
      ["LORE"] = "Los últimos príncipes de Cardolan habitaron en Dol Ernil junto a los túmulos de Tyrn Gorthad. Tras la devastación de estas tierras por malvada hechicería y hierro mortal, las ruinas de la fortaleza están ahora embrujadas por los Muertos resucitados."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "39.85S"; 
          ["LONG"] = "50.56W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Gaervarad"; 
      ["PROGRESS"] = "Explora Gaervarad"; 
      ["LORE"] = "Esta ruina desmoronada albergó en su día un poderoso artefacto en lo alto de su torre: Ambossar, el Vandassar de vetas negras. Fue aquí donde los dúnedain forjaron lazos de paz con los amonedain de Cardolan. Los caciques juraron sus votos, y la Gente de las Colinas se hizo obediente... por un tiempo.\n\nAgentes de Angmar destruirían después la torre y harían añicos el Vandassar, lo que llevó a la disolución de los lazos con la Gente de las Colinas y su subsecuente represalia."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "53.61S"; 
          ["LONG"] = "53.53W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Gond Orchal"; 
      ["PROGRESS"] = "Explora Gond Orchal"; 
      ["LORE"] = "El tiempo ha borrado la memoria de los constructores que hicieron la piedra erguida en Gond Orchal, y para quién la erigieron. Los ancestros de los amonedain trataron este lugar como un sitio sagrado, pero a lo largo de los años también ha sido testigo de horrores."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "41.46S"; 
          ["LONG"] = "45.44W"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "Haudh Nirui"; 
      ["PROGRESS"] = "Explora Haudh Nirui"; 
      ["LORE"] = "En días pasados, los amonedain construyeron las brillantes salas de piedra de Haudh Nirui, donde yacen sepultados varios de sus señores y familias. Mucho de lo que queda se ha convertido en polvo desde hace tiempo, pero las salas permanecen."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "40.53S"; 
          ["LONG"] = "30.96W"; 
        }; 
      }; 
      };
      [7] = {
      ["NAME"] = "Nímbarth"; 
      ["PROGRESS"] = "Explora Nímbarth"; 
      ["LORE"] = "Antaño una gran fortaleza en el borde del Wadewater, Nímbarth ahora yace en ruinas, hogar de males que sirven al Enemigo contra el cual se pretendía defender."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "49.26S"; 
          ["LONG"] = "31.54W"; 
        }; 
      }; 
      };
      [8] = {
      ["NAME"] = "Nettinglade"; 
      ["PROGRESS"] = "Explora Claro de Redes"; 
      ["LORE"] = "Las leyendas locales hablan de jardines en terrazas que una vez se extendían por la colina conocida como Claro de Redes. Mucho antes de ser el hogar de terribles arañas tejiendo sus sedas mortales, era un hermoso lugar de flores, frutas y fuentes.\n\nSe dice que incluso la Dama Galadriel recorrió los senderos en días antiguos, vagando con una suave sonrisa entre las rosas."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "42.02S"; 
          ["LONG"] = "54.48W"; 
        }; 
      }; 
      };
      [9] = {
      ["NAME"] = "Sarch Vorn"; 
      ["PROGRESS"] = "Explora Sarch Vorn"; 
      ["LORE"] = "En lo profundo del Bosque Viejo, las tumbas inundadas de Sarch Vorn han permanecido ocultas durante muchos años. Tumbas finamente elaboradas marcan los lugares de descanso de nobles y miembros de la realeza, reyes y reinas de épocas pasadas, pero sus nombres están ahora olvidados y las tumbas se han convertido en una guarida del mal.\n\nMás antiguas aún son las piedras erguidas con sus tallas en espiral y símbolos antiguos de un pueblo perdido en el tiempo."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "37.69S"; 
          ["LONG"] = "51.98W"; 
        }; 
      }; 
      };
      [10] = {
      ["NAME"] = "Everstead"; 
      ["PROGRESS"] = "Explora Everstead"; 
      ["LORE"] = "Los rumores afirman que las ruinas de Everstead fueron en su día una pequeña finca perteneciente a una reina de días antiguos. Las torres que otorgaban una vista pintoresca sobre el río Gwathló se han derrumbado desde entonces, y ahora nadie más que la fauna salvaje viene aquí."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "46.39S"; 
          ["LONG"] = "28.51W"; 
        }; 
      }; 
      };
      [11] = {
      ["NAME"] = "Hove Farm"; 
      ["PROGRESS"] = "Explora la Granja Hove"; 
      ["LORE"] = "Aunque no tan establecida como sus vecinos en la Granja Scurloc, la familia Hove ha mantenido una vida precaria en su propia pequeña granja. Sin embargo, en días recientes, la familia ha sido expulsada por asaltantes trasgos del norte."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "42.27S"; 
          ["LONG"] = "36.79W"; 
        }; 
      }; 
      };
      [12] = {
      ["NAME"] = "Tharbad"; 
      ["PROGRESS"] = "Explora Tharbad"; 
      ["LORE"] = "Como el flujo y reflujo del Gwathló, las fortunas de Tharbad han caído, subido y vuelto a caer a lo largo de los siglos. Construida hace mucho tiempo por los númenóreanos como asentamiento y vado, sus puentes, diques y presas han sido destruidos y reconstruidos numerosas veces.\n\nGracias a su posición junto al río y el Camino Norte-Sur, la mayor parte del comercio entre los reinos de Arnor y Gondor pasaba por Tharbad. A medida que los burgueses de la ciudad se enriquecían, los dúnedain se propusieron profundizar el canal en el vado, permitiendo el paso de barcos de mayor calado. Los pantanos y vías fluviales de la Ciénaga de los Cisnes fueron dragados y drenados, construyéndose extensos diques para sostener las tierras de cultivo cercanas.\n\nTharbad creció más grandiosa y próspera a través del comercio con Gondor, los elfos y los enanos. Pero sus enemigos eran muchos, y la ciudad fue a menudo saqueada. Cada vez que fue destruida, la ciudad se recuperó arduamente, sus líderes reparando, reforjando y renovando la calzada. Sin embargo, cuando la Gran Plaga arrasó Cardolan, sus gobernantes ya no pudieron mantener el ritmo de las reparaciones necesarias.\n\nTharbad encontró su desaparición final lentamente, mientras los elementos golpeaban las estructuras debilitadas. Finalmente, después del Invierno Cruel, un deshielo repentino creó un muro de agua impetuoso que diezmó los últimos restos de los cruces sobre el Gwathló y arruinó el Gran Puente de una vez por todas.\n\nAhora la ciudad en ruinas se aferra a las orillas de un río cuyas hambrientas corrientes arrastran cada año más y más de sus restos dentados."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "56.53S"; 
          ["LONG"] = "38.26W"; 
        }; 
      }; 
      };
      [13] = {
      ["NAME"] = "Nagenstones"; 
      ["PROGRESS"] = "Explorar Nagenstones"; 
      ["LORE"] = "El nombre de este hogar una vez exuberante, rodeado por todos lados por aguas fluyentes, se ha perdido en el tiempo. Quizás sus suelos de mármol conocieron una vez el delicado susurro de pies calzados con pantuflas y finas sedas, pero ahora sus muros se desmoronan mientras las garras de los Huargos repiquetean sobre los fríos suelos. La gente cercana se refiere a él ahora como Nagenstones."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "47.17S"; 
          ["LONG"] = "32.37W"; 
        }; 
      }; 
      };
      [14] = {
      ["NAME"] = "Wylvenclove"; 
      ["PROGRESS"] = "Explorar Wylvenclove"; 
      ["LORE"] = "El afloramiento rocoso de Wylvenclove alberga las guaridas de una formidable manada de lobos que merodea las colinas onduladas y túmulos de Ruddymore y Tyrn Gorthad."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "46.15S"; 
          ["LONG"] = "48.76W"; 
        }; 
      }; 
      };
  };
