  [1879450926] = {
      [1] = {
      ["NAME"] = "Placa del juramento"; 
      ["PROGRESS"] = "Descubre la Placa del Juramento"; 
      ["LORE"] = "Aunque desgastada y deteriorada por el tiempo, puedes distinguir algunas palabras inscritas en esta placa. Parecen aludir a los juramentos que se hicieron aquí hace cientos de años, cuando la Gente de las Colinas fue obligada a someterse a los reyes Dúnedain."; 
      ["POINTS"] = {
