  -- Volver a Carn Dûm / Gwathrenost, the Witch-king's Citadel -- Shadows of the Past
  [1879458848] = {
      [1] = {
      ["NAME"] = "Gwathrenost"; 
      ["PROGRESS"] = "Find Gwathrenost"; 
      ["LORE"] = "Looming high above Carn Dûm, Gwathrenost was erected long ago during the reign of the Witch-king of Angmar. It was from this nigh-impregnable fortress that Angmar waged its long war against Arnor, devastating the kingdoms of Arthedain, Cardolan, and Rhudaur. After the battle of Fornost turned against the Witch-king of Angmar, it was to Gwathrenost he fled, but he was overtaken by the forces of Eärnur and Glordindel before he could return to Carn Dûm. With Angmar all but destroyed, it laid abandoned for many years until the False King and Steward of Angmar, Mordirith, brought about the first rebirth of Angmar and summoned those still loyal to the iron crown of the Witch-king of Angmar into his service at Carn Dûm."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "72.84N"; 
          ["LONG"] = "31.19W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Armamentos de los Caídos"; 
      ["PROGRESS"] = "Find the armaments of the fallen"; 
      ["LORE"] = "Although they were slain during the second downfall of Angmar, Múra, an Angmarim sorceress, and Rodakhan, a woman of the Trév Duvárdain, have not been forgotten among the ranks of the Iron Crown. After the Iron Crown returned to Carn Dûm, their weapons of old, a staff and a halberd, were recovered and ceremonially mounted upon the walls of Gwathrenost. Those who approach these should take care not to disturb them, lest they incur the wrath of the Iron Crown."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "73.50N"; 
          ["LONG"] = "49.65E"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Tomo Olvidado"; 
      ["PROGRESS"] = "Find a forgotten tome"; 
      ["LORE"] = "It is rare, indeed, to find this complete volume in such pristine condition. Many of its copies found throughout Middle-earth were mysteriously short of pages, but the Iron Crown has done well to collect them all for those kept within Gwathrenost."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "73.35N"; 
          ["LONG"] = "49.64E"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Tirith Gúlaran"; 
      ["PROGRESS"] = "Find Tirith Gúlaran"; 
      ["LORE"] = "From Tirith Gúlaran, the Witch-king of Angmar, and later, Mordirith, the False King and Steward of Angmar, could watch over all of Carn Dûm and its surrounding lands."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "73.53N"; 
          ["LONG"] = "31.21W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Inscripción de Golodir"; 
      ["PROGRESS"] = "Find Golodir's inscription"; 
      ["LORE"] = "It was within this high chamber that Golodir was imprisoned at Gwathrenost, only granted the briefest and most unkind of freedoms on the days he was forced to peer into the palantír at Mordirith's behest. Through all of his suffering, his love for his daughter, Lorniel, never wavered and he dreamt of the day they would at last be reunited. Alas, Mordirith knew well of Golodir's hopes and his faith in those he had left behind at Gath Forthnír...."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "73.65N"; 
          ["LONG"] = "49.87E"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "Tham Mornarcham"; 
      ["PROGRESS"] = "Find Tham Mornarcham"; 
      ["LORE"] = "It was from Tham Mornarcham, long ago, that the Witch-king of Angmar ruled his realm. After he was forced to abandon Angmar, this hall, like all of Carn Dûm, laid empty for many years. However, when Mordirith sought to bring about the rebirth of Angmar, it became the seat of the False King and Steward of Angmar and the high hall of the Iron Crown. It was here that the Ranger Golodir confronted Mordirith in battle, wounded him with the blade, Dúnachar, and forced him into retreat."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "74.01N"; 
          ["LONG"] = "49.65E"; 
        }; 
      }; 
      };
      [7] = {
      ["NAME"] = "Pedestal del Palantír Perdido"; 
      ["PROGRESS"] = "Find the pedestal of the lost palantír"; 
      ["LORE"] = "Kept by the Witch-king of Angmar and, later, the False King and Steward of Angmar, Mordirith, one of the palantíri rested upon this pedestal until the seeing-stone was stolen from Gwathrenost."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "74.06N"; 
          ["LONG"] = "49.69E"; 
        }; 
      }; 
      };
  };
