  -- Volver a Carn Dûm / Alchemy of Thaurisgar
  [1879459078] = {
      [1] = {
      ["NAME"] = "Vómito de guadaña"; 
      ["PROGRESS"] = "Find scythespew"; 
      ["LORE"] = "Scythespew is an odorous and viscous liquid. The phial which contains it is cool to the touch, but the vile substance is used to break down the toughest of flesh. The upper limits of its potency as a corrosive is untested and unknown."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "77.58N"; 
          ["LONG"] = "45.15E"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Sangre de víbora"; 
      ["PROGRESS"] = "Find adder's blood"; 
      ["LORE"] = "The crimson life essence of an adder has many uses in alchemy. In Thaurisgar, it is valuable for its numbing effects, but can be quite deadly if consumed. Ingestion of this substance can result in loss of vital functions. Research suggests it was mainly used as an anesthetic."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "76.32N"; 
          ["LONG"] = "45.26E"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Espuma de huargo"; 
      ["PROGRESS"] = "Find wargslather"; 
      ["LORE"] = "The essence of a warg that has been reduced down to its base innate chemical structure by repeated cycles of steeping and simmering at low temperatures for long durations."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "76.52N"; 
          ["LONG"] = "45.11E"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Sudor purulento"; 
      ["PROGRESS"] = "Find festersweat"; 
      ["LORE"] = "The noxious liquid of festersweat, derived from fungus, is deadly upon physical contact. This concentration has been fermented with other alchemical solutions for long periods of time to create alternative results from its various properties."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "76.30N"; 
          ["LONG"] = "44.92E"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Filtración marchita"; 
      ["PROGRESS"] = "Find strickenseep"; 
      ["LORE"] = "Strickenseep is a highly toxic and deadly sap that is known to cause extreme paralysis and loss of vision. Its uses in alchemy is taboo. Its properties and effects are undesirable. However, when mixed with other substances, Aniochán the Harrower found that its effects and properties could be augmented to avoid the pitfalls of this sap when encountered alone."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "76.65N"; 
          ["LONG"] = "44.98E"; 
        }; 
      }; 
      };
  };
