  [1879466405] = {
      [1] = {
      ["NAME"] = "Calembel"; 
      ["PROGRESS"] = "Find Calembel"; 
      ["LORE"] = "The city of Calembel finds itself a waystation for all manner of goods and people as Gondor seeks to build itself anew."; 
