      [2] = {
      ["NAME"] = "Tathrendalf"; 
      ["PROGRESS"] = "Find Tathrendalf"; 
      ["LORE"] = "Left behind when the war ended, the Corsairs of Tathrendalf find themselves in a precarious position within Lamedon. Neither party knows quite how to handle the other. Perhaps peace can be brokered before tensions come to a head."; 
      ["POINTS"] = {
