      };
      [3] = {
      ["NAME"] = "Lang Boha"; 
      ["PROGRESS"] = "Find Lang Boha"; 
      ["LORE"] = "Once the site of the Corsair and Haradrim landing, Lang Boha remains a desolate and barren reminder of the war's ravages on Dor-en-Ernil. It has been left to ruin, and the local fauna have taken over. If the people of Gondor are to rebuild, Lang Boha must be taken back."; 
      ["POINTS"] = {
