  [1879466408] = {
      [1] = {
      ["NAME"] = "Dol Amroth"; 
      ["PROGRESS"] = "Find Dol Amroth"; 
      ["LORE"] = "Dol Amroth is the seat of Imrahil, the Prince of Belfalas, and is home to the noble and legendary swan-knights. With the siege of the Corsairs broken, the city's ports now lay open and ships are free to pass through the Bay of Belfalas once more."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "74.97S"; 
          ["LONG"] = "71.07W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Abedec's Watch"; 
      ["PROGRESS"] = "Find Abadec's Watch"; 
      ["LORE"] = "What was once a Corsair stronghold remains now as an echo of its former self. Corsairs who have found themselves stranded in Gondor have flocked here out of a desire for safety, vengeance, or both."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "80.73S"; 
          ["LONG"] = "68.77W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Amon Lontir"; 
      ["PROGRESS"] = "Find Amon Lontir"; 
      ["LORE"] = "During the war, the vantage point of Amon Lontir gave beacon-wardens a clear view of the Corsair invasion in the bay. Nowadays, it offers the calming sight of Belfalas at peace."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "74.26S"; 
          ["LONG"] = "66.21W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Edhellond"; 
      ["PROGRESS"] = "Find Edhellond"; 
      ["LORE"] = "Corsairs occupied the crumbling ruins of Edhellond during the war. Now, the Elves of the Avorrim work tirelessly to turn the harbour into a garden."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "72.38S"; 
          ["LONG"] = "67.01W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Hashadir"; 
      ["PROGRESS"] = "Find Hashadir"; 
      ["LORE"] = "The Corsairs of Umbar have been driven away from Hashadir, but they left behind a significant rodent infestation among their destroyed tents. The shores too, have reverted back to nature, with a populace of enormous crabs taking up residence on the sandy beaches."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "78.94S"; 
          ["LONG"] = "72.47W"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "Makham Mijann"; 
      ["PROGRESS"] = "Find Makham Mijann"; 
      ["LORE"] = "Following the Corsairs' abandonment of Makham Mijann, the residents of Tadrent attempted to dismantle the camp for various crafting materials. These efforts paused during the king's coronation, and bog-lurkers began creeping in."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "71.57S"; 
          ["LONG"] = "62.40W"; 
        }; 
      }; 
      };
      [7] = {
      ["NAME"] = "Nendath"; 
      ["PROGRESS"] = "Find Nendath"; 
      ["LORE"] = "Once overrun by Corsairs, Nendath has since been reclaimed by the beacon-wardens."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "75.19S"; 
          ["LONG"] = "61.49W"; 
        }; 
      }; 
      };
      [8] = {
      ["NAME"] = "Ost Lontir"; 
      ["PROGRESS"] = "Find Ost Lontir"; 
      ["LORE"] = "The undercurrent of anxiety that permeated Ost Lontir in the days of the war has dissipated since. But as the closest settlement to Amon Lontir, its townsfolk remain vigilant for other troubles during this time of change."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "74.97S"; 
          ["LONG"] = "65.47W"; 
        }; 
      }; 
      };
      [9] = {
      ["NAME"] = "Ost Amondal"; 
      ["PROGRESS"] = "Find Ost Amondal"; 
      ["LORE"] = "Crumbling ruins are all that remain of the once-proud Gondorian fortress of Ost Amondal. Access to the site has been cut off for many years, but with the opening of the pass in Belfalas, it is possible once more to walk among the ancient walls. A dangerous clutch of drakes has moved into the area, however, making exploration nigh impossible for most."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "82.56S"; 
          ["LONG"] = "62.71W"; 
        }; 
      }; 
      };
      [10] = {
      ["NAME"] = "Tadrent"; 
