  -- Las Islas Escudo / Denizens of the Shield Isles
  [1879469676] = {
      [1] = {
      ["NAME"] = "Fin del viaje"; 
      ["PROGRESS"] = "Find Voyage's End"; 
      ["LORE"] = "The waters that surround Zîrar Tarka are treacherous for the unprepared, but even skilled mariners can stray too near the isles when storms arise in the Bay of Belfalas, to their deep sorrow. If they have the luck of the Valar, some of their crew survive to see the dawning sun that peeks through the forest canopy at Voyage's End. If they do not only the shattered hulks remain, standing in the water beside the island chain, decorating the smile of Shedax Khîn, the Grinding Jaws, from that day forward."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "0.72S"; 
          ["LONG"] = "130.19W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Halrax"; 
      ["PROGRESS"] = "Find Halrax"; 
      ["LORE"] = "The sizeable settlement of Halrax is located on Zamarzîr, the largest of the isles that make up the chain of Zîrar Tarka. It was built over a period of many years by the freebooters of the Bay of Belfalas, and although most of its residents come and go every few years, in this they remain consistent: they prize their freedom and individuality above all else, and answer to none but themselves. Halrax has become a place for the lost, where those who have nowhere else to go sometimes find themselves, through no plan of their own."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "10.00S"; 
          ["LONG"] = "126.30W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Kafagur"; 
      ["PROGRESS"] = "Find Kafagur"; 
      ["LORE"] = "Residents elsewhere in Zîrar Tarka believe the northern island of Jeb Khâtel to be uninhabited, and the Orkish voices that carry from the high cliffs of that place do little to encourage their visitation. But Kafagur has become the new home of a number of unexpected travellers, far from their ancestral lands."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "0.55N"; 
          ["LONG"] = "135.10W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Phadâl Bimai"; 
      ["PROGRESS"] = "Find Phadâl Bimai"; 
      ["LORE"] = "'Listen well to me, friend,' Manadhon says carefully, filling a mug almost to the top with ale. The bartender of Halrax keeps his eyes trained on you, but his pour is so well-practised that not a drop is spilled.\n\n'No one goes that far to the north. Do you know why?'\n\nYou shake your head.\n\n'In the Umbari language, Phadâl Bimai... it means 'Wreckage of the Brutes.' You are better off staying here, believe me. It has a dangerous reputation.'"; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "5.34N"; 
          ["LONG"] = "136.72W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Aklâradum"; 
      ["PROGRESS"] = "Find Aklâradum"; 
      ["LORE"] = "'Where did you hear that name?' Manadhon asks, and you say you heard someone mention it in passing. The bartender of Halrax thinks for a moment.\n\n'I have never climbed up to it myself, but I have felt the chill in my bones when the one who lives there has flown over the town, the shadow of her vast wings falling upon me. I think it is an ill omen, friend, and you would be wise to forget the name Aklâradum. She lives there, and as long as she stays home we can live in peace. At least... that is what I have always believed.'"; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "12.10S"; 
          ["LONG"] = "125.48W"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "Irkhadâr"; 
      ["PROGRESS"] = "Find Irkhadâr"; 
      ["LORE"] = "'You cannot spend long on the island of Zamarzîr without noticing the great caldera beside our town,' Manadhon muses at sunset one night. 'It was not always a lake, you know. They say it used to be a volcano... let us hope it remains dormant. That name, though... sometimes I wonder if the name speaks true.'\n\nYou ask Manadhon the name of which he speaks, and he looks you in the eye.\n\n'Irkhadâr,' he says. 'In the Umbari language it means 'The Sleeper.''"; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "11.65S"; 
          ["LONG"] = "126.00W"; 
        }; 
      }; 
      };
  };
  -- Las Islas Escudo / Perils of the Shield Isles
  [1879469677] = {
      [1] = {
      ["NAME"] = "Basha Ghând"; 
      ["PROGRESS"] = "Find Basha Ghând"; 
      ["LORE"] = "Basha Ghând, the 'hungry bog,' is located on the northern side of Bakhjâd. Corsairs of Mâr Naphra have disappeared in this area during recent weeks, but whether they ran afoul of natural hazards or some type of beast is currently unknown."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "2.71S"; 
          ["LONG"] = "131.32W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Khataj Mârsa"; 
      ["PROGRESS"] = "Find Khataj Mârsa"; 
      ["LORE"] = "Corsairs have taken up residence here at Khataj Mârsa, giving them easy access to the islands that make up Bakhjâd to the north-west and the large island of Zamarzîr to the south-east."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "7.05S"; 
          ["LONG"] = "128.85W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Bâkhabar"; 
      ["PROGRESS"] = "Find Bâkhabar"; 
      ["LORE"] = "The pestilential creatures known as kergrim are drawn to death and the dying, and there have been both at this site of wrecks and ruins. Many sailors have fallen into the sailor's grave that is Bâkhabar."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "7.00S"; 
          ["LONG"] = "131.85W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Ghax-hophra"; 
      ["PROGRESS"] = "Find Ghax-hophra"; 
      ["LORE"] = "This island is home to a species of beetle that scurries all over the rocks north of Jeb Khâtel. Few locations throughout Zîrar Tarka have been named as appropriately as Ghax-hophra, which means 'living burrow' in the Umbari language."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "3.52N"; 
          ["LONG"] = "135.60W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Jeb Lipha"; 
      ["PROGRESS"] = "Find Jeb Lipha"; 
      ["LORE"] = "The sound of the ferocious drakes that crawl upon Jeb Lipha carries a great distance over the water, warning those who travel in Zîrar Tarka not to approach this place, which means 'serpent-stone' in the Umbari language."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "0.31N"; 
          ["LONG"] = "132.49W"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "Dor Pherkha"; 
      ["PROGRESS"] = "Find Dor Pherkha"; 
      ["LORE"] = "Dor Pherkha, the 'cat's cleft,' is located on the southern side of Jeb Khâtel. It may be partially responsible for the island's reputation, for anyone who draws too near the creatures living here are likely to become their prey, and tonight's meal can bring no tales forth from the island."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "0.67S"; 
          ["LONG"] = "134.50W"; 
        }; 
      }; 
      };
      [7] = {
      ["NAME"] = "Maj Khibi"; 
      ["PROGRESS"] = "Find Maj Khibi"; 
      ["LORE"] = "Maj Khibi, the 'netted grove,' is home to a particularly unpleasant breed of spider. It is said that in years past this place had other denizens, but once the spiders decided to move in none desired to stay for long."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "1.79N"; 
          ["LONG"] = "135.94W"; 
        }; 
      }; 
      };
      [8] = {
      ["NAME"] = "Injakhûr"; 
      ["PROGRESS"] = "Find Injakhûr"; 
      ["LORE"] = "Corsairs camp beside the lagoon decorated with the shipwrecks torn apart by the Grinding Jaws of Shedax Khîn. Is it because the broken hulls remind them of nature's cruelty or the whims of the Valar? Or is it because the newly-created wrecks may provide easy pickings for seekers of treasure? None can say for certain."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "1.83S"; 
          ["LONG"] = "127.90W"; 
        }; 
      }; 
      };
      [9] = {
      ["NAME"] = "Bax Garâkh"; 
      ["PROGRESS"] = "Find Bax Garâkh"; 
      ["LORE"] = "Bax Garâkh, the 'drowning shallows,' are located to the east of Bakhjâd. Despite the possibility of finding valuable treasure among the wrecks torn apart by Shedax Khîn, few dare to trespass. It is said the Dead guard that treasure, and only the very foolish or the very fortunate would risk their wrath."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "4.17S"; 
          ["LONG"] = "127.65W"; 
        }; 
      }; 
      };
      [10] = {
      ["NAME"] = "Ghar Jâdam"; 
      ["PROGRESS"] = "Find Ghar Jâdam"; 
      ["LORE"] = "Ghar Jâdam, the 'grotto of bones,' is located on Zamarzîr, the largest island of the chain that makes up Zîrar Tarka. It is home to jungle-beasts of great size and strength, and the wiser residents of Halrax have learned to give the creatures a wide berth. The less wise among them have gone on to decorate the grotto themselves."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "6.46S"; 
          ["LONG"] = "126.64W"; 
        }; 
      }; 
      };
      [11] = {
      ["NAME"] = "Dar Grekhûl"; 
      ["PROGRESS"] = "Find Dar Grekhûl"; 
      ["LORE"] = "Dar Grekhûl, the 'lizard-home,' can be found on the eastern side of Zamarzîr. The legs of the salamanders that live here are said to be a culinary delicacy, if you can discover the correct means of preparing them. Any of the residents of Halrax who know the secret, however, are not inclined to share it."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "9.28S"; 
          ["LONG"] = "123.45W"; 
        }; 
      }; 
      };
      [12] = {
      ["NAME"] = "Baj Khatûg"; 
      ["PROGRESS"] = "Find Baj Khatûg"; 
      ["LORE"] = "Baj Khatûg, the 'slashing shore,' is a wide beach on the south-eastern island of Zîrar Tarka, nearest to the Cape of Umbar. It is home to large crabs that both pinch and scuttle. Rumour has it their meat is delicious, if you can avoid the pinching and overcome the scuttling."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "11.69S"; 
          ["LONG"] = "120.92W"; 
        }; 
      }; 
      };
  };
