  -- Umbar Baharbêl / Umbar Baharbêl, the City of the Corsairs
  [1879477633] = {
      [1] = {
      ["NAME"] = "Calatirion / Torre del faro de Elendil"; 
      ["PROGRESS"] = "Find Calatirion, the Beacon-tower"; 
      ["LORE"] = "You have discovered Calatirion, the Beacon-tower, which was raised by King Elendil to celebrate his victory over Sauron. However, the tower would not stand forever, for the Dark Lord's servants were not gone, and they would return in a later age. At the command of the Forsaken Reaver, one of the Nazgûl, the Calatirion was toppled. The day of its downfall came to be called the Death of Light, and the horror of it is remembered still by the oldest residents of the city."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "19.88S"; 
          ["LONG"] = "103.85W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Wharf-beacon"; 
      ["PROGRESS"] = "Find the Wharf-beacon"; 
      ["LORE"] = "You have discovered the Wharf-beacon, which welcomes ships arriving to the Sail-haven from long voyages away at sea, guiding them to safety when they arrive at night."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "20.00S"; 
          ["LONG"] = "100.87W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Northern Ship-yard"; 
      ["PROGRESS"] = "Find the Northern Ship-yard"; 
      ["LORE"] = "In the Umbari tongue, the locations where stand the great bones of ships under construction are called Jâsh-bithi. This is the northernmost of the two largest, and it is overseen by Ahûd, who has worked among the ships of the Sail-haven for many years."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "18.84S"; 
          ["LONG"] = "100.15W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Southern Ship-yard"; 
      ["PROGRESS"] = "Find the Southern Ship-yard"; 
      ["LORE"] = "In the Umbari tongue, the locations where stand the great bones of ships under construction are called Jâsh-bithi. This is the southernmost of the two largest, and it is overseen by Râmax, who has sworn to see the Heirsworn who remain in the Sail-haven defeated at last."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "21.37S"; 
          ["LONG"] = "98.64W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Harbour-warden's Tower"; 
      ["PROGRESS"] = "Find the Harbour-warden's Tower"; 
      ["LORE"] = "Eshmun, the Captain of the Haven, keeps a careful watch upon the goings-on throughout the Sail-haven from his post at the Harbour-warden's Tower. He is a loyal ally of the Kindred of the Coins and eagerly awaits the return of Tumúldo Fierce-water, who he expects to sail back to Umbar any day now."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "20.10S"; 
          ["LONG"] = "99.25W"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "Dâr Irkant / Sala de subastas"; 
      ["PROGRESS"] = "Find Dâr Irkant"; 
      ["LORE"] = "You have discovered Dâr Irkant, the auction house of Umbar, through which a great deal of currency flows both into and from the coffers of the Upper Ward's merchant families. Hármelak, the Golden Queen, keeps a careful eye upon the business conducted at Dâr Irkant."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "17.93S"; 
          ["LONG"] = "98.31W"; 
        }; 
      }; 
      };
      [7] = {
      ["NAME"] = "Baths of Ilmai Iforikh"; 
      ["PROGRESS"] = "Find the Baths of Ilmai Iforikh"; 
      ["LORE"] = "You have discovered the Baths of Ilmai Iforikh, known to local residents as the Flowering Waters. The peaceful tranquility of these baths are reputed to soothe both body and mind."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "18.03S"; 
          ["LONG"] = "98.86W"; 
        }; 
      }; 
      };
      [8] = {
      ["NAME"] = "Bith Gabâr / El Foro"; 
      ["PROGRESS"] = "Find Bith Gabâr"; 
      ["LORE"] = "You have discovered Bith Gabâr, the grand forum and meeting-place of the Upper Ward. It retains an air of enduring permanence granted to it by the presence of abundant Númenórean architecture, and has been known to draw folk of all sorts who wish to draw attention to themselves or their activities."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "18.30S"; 
          ["LONG"] = "97.84W"; 
        }; 
      }; 
      };
      [9] = {
      ["NAME"] = "Dâr Laja / Sala de reuniones"; 
      ["PROGRESS"] = "Find Dâr Laja"; 
      ["LORE"] = "You have discovered Dâr Laja, the Meeting-hall, located at the head of the great forum in the Upper Ward. This hall is one of the remaining intact Númenórean structures in the city, and is the location where the Kindred of the Coins often convene for official business."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "18.60S"; 
          ["LONG"] = "97.50W"; 
        }; 
      }; 
      };
      [10] = {
      ["NAME"] = "Dâr Jeraf / Casa de la Sabiduría"; 
      ["PROGRESS"] = "Find Dâr Jeraf"; 
      ["LORE"] = "You have discovered Dâr Jeraf, the grand academy of the Tor-gardens that was once known as the House of Wisdom. It was destroyed by servants of the Church of the All-Seeing, and now only rubble remains as a reminder of the damage done by the followers of Sauron."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "17.95S"; 
          ["LONG"] = "96.83W"; 
        }; 
      }; 
      };
      [11] = {
      ["NAME"] = "Kamîr Kateb / Scriptorium"; 
      ["PROGRESS"] = "Find Kamîr Kateb"; 
      ["LORE"] = "You have discovered Kamîr Kateb. the scriptorium that once held countless records and histories of Umbar Baharbêl. Now it has fallen into disrepair and disuse, and the Chambers of Records gather only dust."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "18.26S"; 
          ["LONG"] = "96.67W"; 
        }; 
      }; 
      };
      [12] = {
      ["NAME"] = "Dâr Tabib / Boticario"; 
      ["PROGRESS"] = "Find Dâr Tabib"; 
      ["LORE"] = "You have discovered Dâr Tabib, the partially-ruined apothecary that was known at one time as the House of Healers. Like other structures of learning and knowledge in the Tor-gardens, the Church of the All-seeing exacted a cruel toll upon Dâr Tabib."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "18.67S"; 
          ["LONG"] = "96.88W"; 
        }; 
      }; 
      };
      [13] = {
      ["NAME"] = "Dahâl Huliz / La Arena"; 
      ["PROGRESS"] = "Find Dahâl Huliz"; 
      ["LORE"] = "You have discovered Dahâl Huliz, the grand gladiatorial arena of Umbar Baharbêl. Much blood has been spilt in the arena during many years of the city's history, and on the night of the Sea-stone Mutiny, even more was spilled when Rothog the Storm turned his gaze upon the Heirs of Castamir spectating in the stands."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "19.32S"; 
          ["LONG"] = "95.62W"; 
        }; 
      }; 
      };
      [14] = {
      ["NAME"] = "Baths of Kadax"; 
      ["PROGRESS"] = "Find the Baths of Kadax"; 
      ["LORE"] = "You have discovered the Baths of Kadax, where citizens of the Lower Ward are encouraged to find a respite from the grime and dust of the city."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "20.18S"; 
          ["LONG"] = "96.86W"; 
        }; 
      }; 
      };
      [15] = {
      ["NAME"] = "The Fathomwell"; 
      ["PROGRESS"] = "Find the Fathomwell"; 
      ["LORE"] = "You have discovered the Fathomwell, a deep and wide pool that collects sea-water that can then be put to use by residents of the city or for fighting fires. Two fishermen come to the Fathomwell every day, and have done so without fail since they were children."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "21.04S"; 
          ["LONG"] = "96.55W"; 
        }; 
      }; 
      };
      [16] = {
      ["NAME"] = "The Gut"; 
      ["PROGRESS"] = "Find the Gut"; 
      ["LORE"] = "You have discovered the Gut, a warren of narrow streets and alleys that is not especially safe for outsiders to dare unless they keep a careful watch upon their belongings. Residents of the Gut are a hardy sort, and suspicious of outsiders or folk from the wealthier regions of the city. The Sea-stone Mutiny began in the Gut and areas nearby."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "21.59S"; 
          ["LONG"] = "96.91W"; 
        }; 
      }; 
      };
      [17] = {
      ["NAME"] = "Cuartel"; 
      ["PROGRESS"] = "Find the Barracks"; 
      ["LORE"] = "You have discovered the Barracks, where soldiers of the Fleet-fast are outfitted with armour and weapons for their guard duty and given their assignments."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "23.73S"; 
          ["LONG"] = "100.24W"; 
        }; 
      }; 
      };
      [18] = {
      ["NAME"] = "Baths of Ishkun"; 
      ["PROGRESS"] = "Find the Baths of Ishkun"; 
      ["LORE"] = "You have discovered the Baths of Ishkun, where soldiers of the Fleet-fast are permitted to wash the grime from their clothes after their shifts."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "23.03S"; 
          ["LONG"] = "100.23W"; 
        }; 
      }; 
      };
      [19] = {
      ["NAME"] = "Soldiers' Mess-hall"; 
      ["PROGRESS"] = "Find the Soldiers' Mess-hall"; 
      ["LORE"] = "You have discovered the Soldiers' Mess-hall, where guards on duty in the Fleet-fast take their meals."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "23.59S"; 
          ["LONG"] = "99.48W"; 
        }; 
      }; 
      };
      [20] = {
      ["NAME"] = "Gaol"; 
      ["PROGRESS"] = "Find the Fleet-fast Gaol"; 
      ["LORE"] = "You have discovered the Fleet-fast Gaol, where those who are found guilty of committing crimes are held until it is determined what should be done with them. Many of these folk choose trial-by-combat in the arena as a means of earning their freedom, hoping beyond hope that they are not matched up against Rothog the Storm when their number is drawn."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "23.91S"; 
          ["LONG"] = "99.89W"; 
        }; 
      }; 
      };
      [21] = {
      ["NAME"] = "Parade Ground"; 
      ["PROGRESS"] = "Find the Fleet-fast Parade Ground"; 
      ["LORE"] = "You have discovered the Fleet-fast Parade Ground, where soldiers march before the assembled leaders of the Kindred of the Coins. Such gatherings have not been common of late, but in time of peace, when ceremony is required, the Parade Grounds will be ready."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "22.30S"; 
          ["LONG"] = "99.19W"; 
        }; 
      }; 
      };
      [22] = {
      ["NAME"] = "Stûna"; 
      ["PROGRESS"] = "Find the Stûna"; 
      ["LORE"] = "You have discovered the Stûna, where ships of the Corsairs dock. Most of the fleet was lost at Pelargir during the War of the Ring, but some ships remain, now under the command of the Kindred of the Coins."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "22.64S"; 
          ["LONG"] = "98.13W"; 
        }; 
      }; 
      };
      [23] = {
      ["NAME"] = "Dâr Rapha / Anfiteatro"; 
      ["PROGRESS"] = "Find Dâr Rapha"; 
      ["LORE"] = "You have discovered Dâr Rapha, the House of Tales, a great amphitheatre constructed by the Númenóreans. It frequently plays host to Umbari singers and storytellers."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "17.29S"; 
