  -- Ambarûl / Dangers in Ambarûl
  [1879491584] = {
      [1] = {
      ["NAME"] = "Khetsok"; 
      ["PROGRESS"] = "Find Khetsok"; 
      ["LORE"] = "Ordâkhai soldiers have established an encampment at Khetsok, on the south side of the Ikorbân River. From here they contest the Dumûri for control of the Wrackwade river-crossing and regulate access to Ambarûl from the south."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "29.10S"; 
          ["LONG"] = "79.79W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Omboha"; 
      ["PROGRESS"] = "Find Omboha"; 
      ["LORE"] = "Soldiers of the Great Southern Empire of Ordâkh who survived the Ambarûli revolt have regrouped at Omboha. Unable to reach their compatriots south of the Ikorbân, they gather their strength while awaiting an unlikely rescue."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "18.11S"; 
          ["LONG"] = "78.04W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Bidrokh-nûn"; 
      ["PROGRESS"] = "Find Bidrokh-nûn"; 
      ["LORE"] = "As the Ordâkhai lose their grip on Ambarûl, lawlessness is on the rise. Cutthroats and ruffians, many of whom are Ordâkhai deserters, have formed a camp at Bidrokh-nûn from which they prey on the locals and any trade caravans using the nearby road."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "23.45S"; 
          ["LONG"] = "78.37W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Sudurûn"; 
      ["PROGRESS"] = "Find Sudurûn"; 
      ["LORE"] = "At the site of a ruin of unknown origin, Ambarûli servals and caracals have made a comfortable home for themselves."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "15.35S"; 
          ["LONG"] = "86.64W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Gurakhu"; 
      ["PROGRESS"] = "Find Gurakhu"; 
      ["LORE"] = "Deep in the Ambarûli marshes, Gurakhu is the nesting place of zizani, the creatures known in other parts of Middle-earth as Neekers."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "19.23S"; 
          ["LONG"] = "83.12W"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "Nirikal"; 
      ["PROGRESS"] = "Find Nirikal"; 
      ["LORE"] = "The dry sands of Nirikal in southern Ambarûl provide the perfect habitat for the usan-kûni, the giant scorpions of Shagâna."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "28.70S"; 
          ["LONG"] = "86.44W"; 
        }; 
      }; 
      };
      [7] = {
      ["NAME"] = "Tûl Ushu"; 
      ["PROGRESS"] = "Find Tûl Ushu"; 
      ["LORE"] = "The hills of Tûl Ushu in north-eastern Ambarûl are home to many usan-kûni, the giant scorpions of Shagâna."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "20.41S"; 
          ["LONG"] = "75.81W"; 
        }; 
      }; 
      };
      [8] = {
      ["NAME"] = "Shegdush"; 
      ["PROGRESS"] = "Find Shegdush"; 
      ["LORE"] = "Shegdush, 'swine-home' in Shagani, is the favoured stomping ground of the wild boars of eastern Ambarûl."; 
