      [10] = {
      ["NAME"] = "Eshadûr"; 
      ["PROGRESS"] = "Find Eshadûr"; 
      ["LORE"] = "Once the primary fishing village of Ambarûl, Eshadûr has fallen to Ordâkhai occupation. After being defeated by Girhâzi and the Ambarûli revolt, the majority of Ordâkhai forces fled south of the Ikorbân, pushed out Eshadûr's former residents, and made it their new base of operations. From here they test the Dumûri defences and await reinforcements from the south so that they may take Iridír and northern Ambarûl back into their control."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "22.30S"; 
          ["LONG"] = "84.95W"; 
        }; 
      }; 
      };
  };
  -- Ambarûl / Scouting Ambarûl
  [1879491585] = {
      [1] = {
      ["NAME"] = "Iridír"; 
      ["PROGRESS"] = "Find Iridír"; 
      ["LORE"] = "Built upon wooden pilings above the marsh, Iridír is the primary village of Ambarûl. A home to farmers, fishers, and crafters, it is no longer the centre of trade it once was. After throwing off the yoke of their Ordâkhai oppressors, Girhâzi and the other residents of Iridír work to restore trade to the village while also maintaining Ambarûl's independence."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "22.14S"; 
          ["LONG"] = "80.64W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Sûru"; 
      ["PROGRESS"] = "Find Sûru"; 
      ["LORE"] = "Situated on the north shore of the Wrackwade, Sûru is a Dumûri fortification that allows them to maintain control of the only river-crossing in Ambarûl. Archers' towers being built at Sûru will help the Dumûri defend the river-crossing as well as enable them to watch over the road, protecting travellers and trade caravans."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "26.83S"; 
          ["LONG"] = "77.11W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Telperiën's Wall"; 
      ["PROGRESS"] = "Find Telperiën's Wall"; 
      ["LORE"] = "Built by Númenor during the reign of Tar-Telperiën, the wall was constructed as a barrier to protect its haven of Vëalondë, now Umbar, from the native peoples. Telperiën's Wall was destroyed by earthquakes in the Second Age and later by the Hamâti using Narghâk when they conquered Umbar."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "17.44S"; 
          ["LONG"] = "89.67W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Span of Zibâla"; 
      ["PROGRESS"] = "Find The Flood-span"; 
      ["LORE"] = "The remains of a tall, arched bridge built in the early years of the Third Age for the Road of Riches to cross the Ikorbân. Also known as the Span of Zibâla, it was destroyed by the Ambarûli about one hundred years ago in an effort to keep the hosts of Ordâkh at bay. This act of destruction only slowed the Ordâkhai advance and did not stop them."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "22.55S"; 
          ["LONG"] = "82.40W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Wrackwade"; 
      ["PROGRESS"] = "Find the Wrackwade"; 
      ["LORE"] = "A series of rafts strung together make up the Wrackwade, the only river-crossing currently in Ambarûl. The makeshift bridge was built following the destruction of the Flood-span about one hundred years ago, and is presently the main object of conflict between the Dumûri and the remaining Ordâkhai in Ambarûl."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "28.07S"; 
          ["LONG"] = "78.46W"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "Burukíri"; 
      ["PROGRESS"] = "Find Burukíri"; 
      ["LORE"] = "An orange grove still in operation, this orchard provides fruit to Ambarûl, with enough left over to trade with neighbouring communities."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "18.60S"; 
          ["LONG"] = "80.66W"; 
        }; 
      }; 
      };
      [7] = {
      ["NAME"] = "Asha Mûn"; 
      ["PROGRESS"] = "Find Asha Mûn"; 
      ["LORE"] = "Long ago rock salt was collected from these mines when Ambarûl was a centre of trade in Shâgana. The tunnels have been long abandoned, as workers have been made to focus on farming to provide food for the less fertile lands controlled by the Empire of Ordâkh. Most people dare not enter the old mines, as they are known to be infested with usan-kûni."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "19.60S"; 
          ["LONG"] = "77.78W"; 
        }; 
      }; 
      };
      [8] = {
      ["NAME"] = "Mehêtur"; 
      ["PROGRESS"] = "Find Mehêtur"; 
      ["LORE"] = "Mehêtur is a working papyrus farm. Papyrus the plant is cultivated here and is then processed into papyrus the writing surface. Without the Ordâkhai presence, there is little demand for papyrus in Ambarûl, as the agrarian population is largely illiterate."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "20.75S"; 
          ["LONG"] = "82.23W"; 
        }; 
      }; 
      };
      [9] = {
      ["NAME"] = "Ekagar"; 
      ["PROGRESS"] = "Find Ekagar"; 
      ["LORE"] = "Ekagar is a working rice farm on the northern shores of the Ikorbân. Rice is an ideal crop to grow in the marshes of Ambarûl, and is a staple of the local diet. It is also an excellent trade-good as it can be dried, making it easy to store and transport."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "18.77S"; 
          ["LONG"] = "85.55W"; 
        }; 
      }; 
      };
      [10] = {
      ["NAME"] = "Gishtir"; 
      ["PROGRESS"] = "Find Gishtir"; 
      ["LORE"] = "A small, newly-founded lumber camp, Gishtir was established with the hope of harvesting the trees with higher quality wood in a nearby grove."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "15.04S"; 
          ["LONG"] = "78.92W"; 
        }; 
      }; 
      };
      [11] = {
      ["NAME"] = "Arwáth"; 
      ["PROGRESS"] = "Find Arwáth"; 
      ["LORE"] = "A hard-to-find grove of old trees near the northern edge of Ambarûl, Arwáth was long rumoured to be haunted. In reality, it is an oasis-dwelling of the Kinta Elves, currently occupied only by a sole warden and the spirits of the Kintai who faded there."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "13.80S"; 
          ["LONG"] = "79.18W"; 
        }; 
      }; 
      };
      [12] = {
      ["NAME"] = "Dubarâkh"; 
      ["PROGRESS"] = "Find the Dubarâkh"; 
      ["LORE"] = "When the Empire of Ordâkh outlawed literacy for the native Ambarûli, followers of the Old Ways scrambled to collect all of the scrolls and books relating to the history and culture of Ambarûl in an effort to save them from destruction. This collection of documents was hidden for its preservation, and the location of where it is stored has long been forgotten."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "54.06N"; 
          ["LONG"] = "145.69W"; 
        }; 
      }; 
      };
      [13] = {
      ["NAME"] = "Esh Enûn"; 
      ["PROGRESS"] = "Find Esh Enûn"; 
      ["LORE"] = "This fane of Barkhûsh, a temple of Sauron, the All-seeing, is nothing more than a burnt husk after the Ambarûli revolt, led by Girhâzi, destroyed it months ago. It was once the home to Sauron's priests, who subjected the local population to their Lord's will. Almost immediately upon learning of the defeat of both the Dark Lord and the Emperor of Ordâkh, the peasants of Ambarûl burned and destroyed the temple along with its evil priests."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "22.49S"; 
          ["LONG"] = "79.26W"; 
        }; 
      }; 
      };
      [14] = {
      ["NAME"] = "Gha Nêkha"; 
      ["PROGRESS"] = "Find Gha Nêkha"; 
      ["LORE"] = "A small outpost south of the Ikorbân, Gha Nêkha was built to provide water and shelter for weary travellers navigating the desert of southern Ambarûl. Though it is near Eshadûr, the Ordâkhai have thus far shown no interest in the small settlement."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "25.44S"; 
          ["LONG"] = "84.66W"; 
        }; 
      }; 
      };
  };
