  -- Mûr Ghala / New Threats in Adagím
  [1879513778] = {
      [1] = {
      ["NAME"] = "Hordírid"; 
      ["PROGRESS"] = "Find Hordírid"; 
      ["LORE"] = "The trees of Hordírid have grown fierce and dangerous with the spreading rot in Adagím. The patch of land known by locals as the Wokenhurst is now a warning to travellers seeking to venture into the northern parts of the forest."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "36.73S"; 
          ["LONG"] = "47.22W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Thor Lhîg"; 
      ["PROGRESS"] = "Find Thor Lhîg"; 
      ["LORE"] = "The roots from the Hill of the Mother reach deep into the earth in Thor Lhîg, spreading the rot deep within the trees as they succumb to the Pale Blight. The once beautiful trees are now tainted in the shadow of the tree that once nourished them."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "38.33S"; 
          ["LONG"] = "39.96W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Hadrudád"; 
      ["PROGRESS"] = "Find Hadrudád"; 
      ["LORE"] = "The trees of Hadrudád have not felt the pain of the blight as much as other place in Adagím with green still visible on the earth, but it has not been immune. The trees here still fester with rot and have become deadly for travellers. The scouts of Sâr Marsag to the east hold them at bay as they keep the roads to Kighân safe."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "48.00S"; 
          ["LONG"] = "48.00W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Ogultáth"; 
      ["PROGRESS"] = "Find Ogultáth"; 
      ["LORE"] = "Ogultáth is a dense patch of forest now known to the Kintai as 'spider-hollow'. The blight in the land has corrupted the spiders here and heightened their aggression as they expand their webs further into the land."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "35.90S"; 
          ["LONG"] = "43.63W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Dathrudúsh"; 
      ["PROGRESS"] = "Find Dathrudúsh"; 
      ["LORE"] = "The Kintai call this place the weaver's house as Dathrudúsh has been home to the spiders who dwell deep in the marsh for many years. The roots of the mother tree now push the blight out from the earth and taint the creatures here."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "42.25S"; 
          ["LONG"] = "42.12W"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "Narchásh"; 
      ["PROGRESS"] = "Find Narchásh"; 
      ["LORE"] = "The spiders of Narchásh have earned the name given to them by the Kintai. The hole of rending as it is known, due to their vicious nature of preying on travellers unfortunate enough to step through their webs. The spiders now rotten with blight spread the poison across the land to weaken their potential targets."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "44.95S"; 
          ["LONG"] = "49.58W"; 
        }; 
      }; 
      };
      [7] = {
      ["NAME"] = "Thalat Tîr"; 
      ["PROGRESS"] = "Find Thalat Tîr"; 
      ["LORE"] = "Known as the vale of the devourers, the spiders of Thalat Tîr fester with rot as it blooms from the Hill of the Mother herself, tainting the earth and creature alike. Here the spiders are well known to the people of Adagím and grow monstrous as they lie in wait for any to pass by."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "39.16S"; 
          ["LONG"] = "38.28W"; 
        }; 
      }; 
      };
      [8] = {
      ["NAME"] = "Pits of Chortáth"; 
      ["PROGRESS"] = "Find the Pits of Chortáth"; 
      ["LORE"] = "The rocky pits of Chortáth are scattered with bones and corpses that belonged to any who venture too deep. It is home to a large pack of jackals who have taken hold of the land, using the maze-like rocks to stalk their prey. The Kinta scouts of Sâr Marsag regularly fight with the beasts to try and gain the upper hand in safeguarding the roads."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "51.22S"; 
          ["LONG"] = "49.66W"; 
        }; 
      }; 
      };
      [9] = {
      ["NAME"] = "Mauthark"; 
      ["PROGRESS"] = "Find Mauthark"; 
      ["LORE"] = "Now known as Mauthark, the forest near the borders of Adagím and Imhular has become a home to Orcs who roam the marsh as the lone allies of the Ordâkhi willing to tolerate the vile conditions as they threaten the borders of the few remaining groves of the Kintai."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "45.19S"; 
          ["LONG"] = "52.31W"; 
        }; 
      }; 
      };
      [10] = {
      ["NAME"] = "Mokh Grazádh"; 
      ["PROGRESS"] = "Find Mokh Grazádh"; 
      ["LORE"] = "Mokh Grazádh has become a stronghold for Orcs in the sickened marsh of Adagím. With its central location in the forest the Orcs here terrorize the Kintai along with any travellers who dare tread these roads. The threat they pose to the Elves grows by the day as their attention is turned towards the Pale Blight."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "42.68S"; 
          ["LONG"] = "45.98W"; 
        }; 
      }; 
      };
      [11] = {
      ["NAME"] = "Lhámuth"; 
      ["PROGRESS"] = "Find Lhámuth"; 
      ["LORE"] = "Lhámuth is home to many lurkers of the marsh. Once a serene grouping of ponds, now poisoned and deadly from the rot in the earth. In recent years the tainted monstrosities that grew from the wood-trolls have begun to roam these lands, disrupting the bog-lurkers as the blight consumes them."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "40.85S"; 
          ["LONG"] = "44.00W"; 
        }; 
      }; 
      };
      [12] = {
      ["NAME"] = "Lair of the Shadlúgai"; 
      ["PROGRESS"] = "Find the Lair of the Shadlúgai"; 
      ["LORE"] = "Named the Lair of the Shadlúgai, the marsh here still holds some green within its waters as they are far from the thick forest and the roots of the mother tree. The Kintai speak of the stone-worms who live here, skulking in the water for any prey that comes too close to their jaws."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "47.2S"; 
          ["LONG"] = "42.40W"; 
        }; 
      }; 
      };
      [13] = {
      ["NAME"] = "Saig Hathíl"; 
      ["PROGRESS"] = "Find Saig Hathíl"; 
      ["LORE"] = "Found along the path to Sul Madásh is Saig Hathíl, the blade-hives in the common tongue. Home to sickleflies seeking out any place they can to avoid the rot. The small patch of green within the marsh that survives through the will of the Kintai has become their nesting grounds until the Pale Blight closes in."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "42.27S"; 
          ["LONG"] = "39.83W"; 
        }; 
      }; 
      };
      [14] = {
      ["NAME"] = "Fushaum Sûlm"; 
      ["PROGRESS"] = "Find Fushaum Sûlm"; 
      ["LORE"] = "The first camp built by the Orcs when they came to Adagím. Fushaum Sûlm is a stronghold deep enough in the marshes that they do not get many attackers but fortified to withstand them all the same. The Orcs use it to scout the Kintai who guard the road into Kighân as well as attack any travellers who try and slip by."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "50.01S"; 
          ["LONG"] = "40.25W"; 
        }; 
      }; 
      };
  };
