  -- Mûr Ghala / Dangers in Pahar Hatokáli
  [1879524270] = {
      [1] = {
      ["NAME"] = "Kakidûr"; 
      ["PROGRESS"] = "Find Kakidûr"; 
      ["LORE"] = "Old-timers in the village of Hanamíku will tell you that there have always been trouble-makers on the hills above the village, and they would be right: before the brigands, Kakidûr was home to Ordâkhai deserters before they moved on. Remnants of the Ordâkhai presence can still be found there, but most of their equipment has been reclaimed and repurposed by local brigands."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "70.24S"; 
          ["LONG"] = "91.65W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Aptíku"; 
      ["PROGRESS"] = "Find Aptíku"; 
      ["LORE"] = "Brigands dwell at Aptíku alongside the shore of the Hatokáli River. Any who speak Nêshakari would recognize the name as meaning 'reed-mist,' and would find it most appropriate. Few aside from their leader are likely to do so."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "79.04S"; 
          ["LONG"] = "89.20W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Mut-hûru"; 
      ["PROGRESS"] = "Find Mut-hûru"; 
      ["LORE"] = "The caverns of Mut-hûru are actually two cave systems, joined through burrowing activity by underground dwellers beneath the Ridge of Plenty. Tombs of the dead, long abandoned by any save kergrim scavengers, stand within the vast and maze-like caverns."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "56.63N"; 
          ["LONG"] = "144.11W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Mûl Erebu"; 
      ["PROGRESS"] = "Find Mûl Erebu"; 
      ["LORE"] = "Good folk abandoned Mûl Erebu; now it is given over only to scorpions and to those who thought to make use of them, to their sorrow."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "74.98S"; 
          ["LONG"] = "90.06W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Bolo Thúki"; 
      ["PROGRESS"] = "Find Bolo Thúki"; 
      ["LORE"] = "Bolo Thúki is the northernmost of the three primary encampments seized by Bârshud's Ordâkhai as they fled south. Here his soldiers attempt to fortify the hillside and make use of the supplies they stole from the village of Hanamíku before the Hamâti army caught up to them."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "72.27S"; 
          ["LONG"] = "87.46W"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "Nakársong"; 
      ["PROGRESS"] = "Find Nakársong"; 
      ["LORE"] = "This is the second of the primary encampments seized by Bârshud's Ordâkhai as they fled into Pahar Hatokáli. Here they keep many of the lions they intend to unleash upon Mizâdi's forces, but the training has not gone entirely smoothly...."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "76.80S"; 
          ["LONG"] = "87.41W"; 
        }; 
      }; 
      };
      [7] = {
      ["NAME"] = "Imizíla"; 
      ["PROGRESS"] = "Find Imizíla"; 
      ["LORE"] = "The fortress of Imizíla, 'last torch' in the Shagâni language, has appropriately become the final bastion for Bârshud's Ordâkhai in Pahar Hatokáli. Trapped between the pursuing forces of Shâra Mizâdi and the raging waters of the Hatokáli River, Imizíla will by necessity be where this army of Ordâkh fights to the end."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "77.28S"; 
          ["LONG"] = "80.96W"; 
        }; 
      }; 
      };
      [8] = {
      ["NAME"] = "Ukh-bâra"; 
      ["PROGRESS"] = "Find Ukh-bâra"; 
      ["LORE"] = "The zizani of Ukh-bâra fill the moist air with the sound of their call, and the underbrush rustles as they move hither and yon on skittering legs. Water splashes nearby but you cannot identify the precise location, and you feel insect eyes upon you.\n\nThis marshy stretch beside the Hatokáli River is full of life. You are eager to leave it behind."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "77.59S"; 
          ["LONG"] = "83.16W"; 
        }; 
      }; 
      };
      [9] = {
      ["NAME"] = "Roz Káskrauz"; 
      ["PROGRESS"] = "Find Roz Káskrauz"; 
      ["LORE"] = "The Orcs of Roz Káskrauz are war-like and aggressive, and while they prefer to remain within their stronghold, they will emerge from it to do battle if they believe they have the upper hand. Until then, they are willing to let the Ordâkhai under Bârshud give their lives as the Hamâti soldiers advance."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "75.26S"; 
          ["LONG"] = "81.71W"; 
        }; 
      }; 
      };
      [10] = {
      ["NAME"] = "Bûlkharar"; 
      ["PROGRESS"] = "Find Bûlkharar"; 
      ["LORE"] = "The alap-nâri oxen dwell at Bûlkharar, beside the Hatokáli River. The atmosphere here is warm and smells of damp hair; an unpleasant combination, though the alap-nâri do not seem to mind."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "77.84S"; 
          ["LONG"] = "92.38W"; 
        }; 
      }; 
      };
  };
  -- Mûr Ghala / Scouting Pahar Hatokáli
  [1879524271] = {
      [1] = {
      ["NAME"] = "MGS Norte"; 
      ["PROGRESS"] = "Find Hanamíku"; 
      ["LORE"] = "The village of Hanamíku serves as a way-station nestled among the rocks of Nêr Abatu, the Gate of Stones that stands between Idagâl and Pahar Hatokáli. It has been a place of peace during the years since the Ordâkhai came north and took up residence at Emax Dûl, but that has changed almost overnight.\n\nSoldiers of Ordâkh fleeing the city passed through Hanamíku on their way south, pursued by the army of Renewed Hamât. Bârshud's forces burned farms and wrought devastation as they fled, seeking to deprive Shâra Mizâdi of help and supplies. Now the villagers fear any who bear weapons, and many mistrust outsiders."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "69.90S"; 
          ["LONG"] = "89.45W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Ingarûma"; 
      ["PROGRESS"] = "Find Ingarûma"; 
      ["LORE"] = "The forces of Renewed Hamât have established the war camp of Ingarûma on a naturally rocky rise midway through Pahar Hatokáli. Many throughout the years have sought to establish camps here for the commanding view it provides of the surrounding fells. Will Shâra Mizâdi be the last?\n\nSoldiers, provisioners, forge-masters, strategists, and scouts have made this their outpost in lands far from their homes. Most are eager to put an end to Bârshud and the forces he commands so they may leave this place, but until that day comes they will endure."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "74.75S"; 
          ["LONG"] = "85.94W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Shûmadir"; 
      ["PROGRESS"] = "Find Shûmadir"; 
      ["LORE"] = "The great bridge of Shûmadir has fallen into disrepair over the years. Unless it is repaired, no army can easily pass this way."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "75.50S"; 
          ["LONG"] = "79.30W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Kirzâmur"; 
      ["PROGRESS"] = "Find Kirzâmur"; 
      ["LORE"] = "The farm of Kirzâmur was burned by the retreating Ordâkhai as they passed south, hoping to prevent its use by Mizâdi's forces. Now Ebnûr and Namtâru seek to maintain a cheerful disposition while they rebuild... easier for the father than it is for his son."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "71.99S"; 
          ["LONG"] = "89.20W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Nar Makâru"; 
      ["PROGRESS"] = "Find Nar Makâru"; 
      ["LORE"] = "Though long-abandoned by their builders, the water-wheels of Nar Makâru turn still. For what purpose do they now run, and on behalf of what commander?"; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "74.38S"; 
          ["LONG"] = "78.45W"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "Sakhar Kishâsya"; 
      ["PROGRESS"] = "Find Sakhar Kishâsya"; 
      ["LORE"] = "Little is remembered today of the tower of Sakhar Kishâsya, save that it was built long ago and is more ancient than the other structures in Pahar Hatokáli. It has sunk into the earth as a result of the Din of Stone and other, even older geologic events."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "76.00S"; 
          ["LONG"] = "81.60W"; 
        }; 
      }; 
      };
      [7] = {
      ["NAME"] = "Pagru-kirít"; 
      ["PROGRESS"] = "Find Pagru-kirít"; 
      ["LORE"] = "In the Nêshakari tongue, Pagru-kirít means 'Garden of Corpses.' Perhaps that is enough to know of this place to which only the desperate should come willingly."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "0.73S"; 
          ["LONG"] = "111.52W"; 
        }; 
      }; 
      };
      [8] = {
      ["NAME"] = "Gates of Eshkhâbul"; 
      ["PROGRESS"] = "Find Gates of Eshkhâbul"; 
      ["LORE"] = "The Gates of Eshkhâbul prevent passage further north and west, keeping the brigands that encamp upon the southern slope of Mûr Ghala from leaving and troubling other lands. This is of little comfort to the villagers of nearby Hanamíku, but they were not consulted by those who shut the gates."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "69.90S"; 
          ["LONG"] = "92.50W"; 
        }; 
      }; 
      };
      [9] = {
      ["NAME"] = "The Roaring Hatokáli"; 
      ["PROGRESS"] = "Find the Roaring Hatokáli"; 
      ["LORE"] = "The sound booms in your ears as the Hatokáli River descends in an overwhelming torrent, rushing downstream with tremendous voice."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "78.65S"; 
          ["LONG"] = "94.26W"; 
        }; 
      }; 
      };
      [10] = {
      ["NAME"] = "Khabur Pâshu"; 
      ["PROGRESS"] = "Find Khabur Pâshu"; 
      ["LORE"] = "The small graveyard of Khabur Pâshu stands beneath the village of Hanamíku and has served as the final resting place of its people since the village was founded."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "68.90S"; 
          ["LONG"] = "89.64W"; 
        }; 
      }; 
      };
  };
